import{J as e,n as t,ot as n,q as r}from"./chunks/framework.NDkVE8yV.js";var i=JSON.parse(`{"title":"Class: PlayerSession","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Class: PlayerSession"}],["meta",{"property":"og:description","content":""}],["meta",{"property":"og:url","content":"https://jsprismarine.dev/api/@jsprismarine/prismarine/network/PlayerSession/classes/PlayerSession"}],["link",{"rel":"canonical","href":"https://jsprismarine.dev/api/@jsprismarine/prismarine/network/PlayerSession/classes/PlayerSession"}]],"editSource":{"kind":"folder","url":"https://github.com/JSPrismarine/JSPrismarine/tree/master/packages/prismarine/src"}},"headers":[],"relativePath":"api/@jsprismarine/prismarine/network/PlayerSession/classes/PlayerSession.md","filePath":"api/@jsprismarine/prismarine/network/PlayerSession/classes/PlayerSession.md","lastUpdated":1794500225000}`),a={name:`api/@jsprismarine/prismarine/network/PlayerSession/classes/PlayerSession.md`};function o(t,i,a,o,s,c){return n(),r(`div`,null,[...i[0]||=[e(`<p><a href="./../../../../../">API reference</a> / <a href="./../../../">@jsprismarine/prismarine</a> / <a href="./../">network/PlayerSession</a> / PlayerSession</p><h1 id="class-playersession" tabindex="-1">Class: PlayerSession <a class="header-anchor" href="#class-playersession" aria-label="Permalink to “Class: PlayerSession”">​</a></h1><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/1e6d90ea19aef765befd07dcc536f23d48c760b1/packages/prismarine/src/network/PlayerSession.ts#L328" target="_blank" rel="noreferrer">prismarine/src/network/PlayerSession.ts:328</a></p><h2 id="constructors" tabindex="-1">Constructors <a class="header-anchor" href="#constructors" aria-label="Permalink to “Constructors”">​</a></h2><h3 id="constructor" tabindex="-1">Constructor <a class="header-anchor" href="#constructor" aria-label="Permalink to “Constructor”">​</a></h3><blockquote><p><strong>new PlayerSession</strong>(<code>server</code>, <code>connection</code>, <code>player</code>, <code>players</code>, <code>world</code>): <code>PlayerSession</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/1e6d90ea19aef765befd07dcc536f23d48c760b1/packages/prismarine/src/network/PlayerSession.ts#L520" target="_blank" rel="noreferrer">prismarine/src/network/PlayerSession.ts:520</a></p><h4 id="parameters" tabindex="-1">Parameters <a class="header-anchor" href="#parameters" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="server" tabindex="-1">server <a class="header-anchor" href="#server" aria-label="Permalink to “server”">​</a></h5><p><a href="./../../../Server/classes/Server.html"><code>Server</code></a></p><p>The server the session belongs to.</p><h5 id="connection" tabindex="-1">connection <a class="header-anchor" href="#connection" aria-label="Permalink to “connection”">​</a></h5><p><code>ClientConnection</code></p><p>The connection it speaks through.</p><h5 id="player" tabindex="-1">player <a class="header-anchor" href="#player" aria-label="Permalink to “player”">​</a></h5><p><code>SessionPlayerRef</code></p><p>The id and identity of the player it speaks for.</p><h5 id="players" tabindex="-1">players <a class="header-anchor" href="#players" aria-label="Permalink to “players”">​</a></h5><p><code>SessionPlayers</code>&lt;<code>StorePlayer</code>&gt;</p><p>Where the player is filed by that id.</p><h5 id="world" tabindex="-1">world <a class="header-anchor" href="#world" aria-label="Permalink to “world”">​</a></h5><p><a href="./../../../world/World/classes/World.html"><code>World</code></a></p><p>The world the login puts the player in, until its record names another.</p><h4 id="returns" tabindex="-1">Returns <a class="header-anchor" href="#returns" aria-label="Permalink to “Returns”">​</a></h4><p><code>PlayerSession</code></p><h2 id="properties" tabindex="-1">Properties <a class="header-anchor" href="#properties" aria-label="Permalink to “Properties”">​</a></h2><h3 id="identity" tabindex="-1">identity <a class="header-anchor" href="#identity" aria-label="Permalink to “identity”">​</a></h3><blockquote><p><code>readonly</code> <strong>identity</strong>: <code>PlayerIdentity</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/1e6d90ea19aef765befd07dcc536f23d48c760b1/packages/prismarine/src/network/PlayerSession.ts#L336" target="_blank" rel="noreferrer">prismarine/src/network/PlayerSession.ts:336</a></p><p>Who logged in on this session.</p><hr><h3 id="runtimeid" tabindex="-1">runtimeId <a class="header-anchor" href="#runtimeid" aria-label="Permalink to “runtimeId”">​</a></h3><blockquote><p><code>readonly</code> <strong>runtimeId</strong>: <code>bigint</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/1e6d90ea19aef765befd07dcc536f23d48c760b1/packages/prismarine/src/network/PlayerSession.ts#L333" target="_blank" rel="noreferrer">prismarine/src/network/PlayerSession.ts:333</a></p><p>The player&#39;s entity id, as the wire carries it.</p><h2 id="accessors" tabindex="-1">Accessors <a class="header-anchor" href="#accessors" aria-label="Permalink to “Accessors”">​</a></h2><h3 id="attributes" tabindex="-1">attributes <a class="header-anchor" href="#attributes" aria-label="Permalink to “attributes”">​</a></h3><h4 id="get-signature" tabindex="-1">Get Signature <a class="header-anchor" href="#get-signature" aria-label="Permalink to “Get Signature”">​</a></h4><blockquote><p><strong>get</strong> <strong>attributes</strong>(): <code>Attributes</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/1e6d90ea19aef765befd07dcc536f23d48c760b1/packages/prismarine/src/network/PlayerSession.ts#L3259" target="_blank" rel="noreferrer">prismarine/src/network/PlayerSession.ts:3259</a></p><p>The client&#39;s attribute table: food, experience and the rest, and a copy of the health.</p><h5 id="returns-1" tabindex="-1">Returns <a class="header-anchor" href="#returns-1" aria-label="Permalink to “Returns”">​</a></h5><p><code>Attributes</code></p><hr><h3 id="gamemode" tabindex="-1">gamemode <a class="header-anchor" href="#gamemode" aria-label="Permalink to “gamemode”">​</a></h3><h4 id="get-signature-1" tabindex="-1">Get Signature <a class="header-anchor" href="#get-signature-1" aria-label="Permalink to “Get Signature”">​</a></h4><blockquote><p><strong>get</strong> <strong>gamemode</strong>(): <a href="./../../../../minecraft/#gametype"><code>Gametype</code></a></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/1e6d90ea19aef765befd07dcc536f23d48c760b1/packages/prismarine/src/network/PlayerSession.ts#L3254" target="_blank" rel="noreferrer">prismarine/src/network/PlayerSession.ts:3254</a></p><p>The game mode.</p><h5 id="returns-2" tabindex="-1">Returns <a class="header-anchor" href="#returns-2" aria-label="Permalink to “Returns”">​</a></h5><p><a href="./../../../../minecraft/#gametype"><code>Gametype</code></a></p><hr><h3 id="pitch" tabindex="-1">pitch <a class="header-anchor" href="#pitch" aria-label="Permalink to “pitch”">​</a></h3><h4 id="get-signature-2" tabindex="-1">Get Signature <a class="header-anchor" href="#get-signature-2" aria-label="Permalink to “Get Signature”">​</a></h4><blockquote><p><strong>get</strong> <strong>pitch</strong>(): <code>number</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/1e6d90ea19aef765befd07dcc536f23d48c760b1/packages/prismarine/src/network/PlayerSession.ts#L3249" target="_blank" rel="noreferrer">prismarine/src/network/PlayerSession.ts:3249</a></p><h5 id="returns-3" tabindex="-1">Returns <a class="header-anchor" href="#returns-3" aria-label="Permalink to “Returns”">​</a></h5><p><code>number</code></p><hr><h3 id="sender" tabindex="-1">sender <a class="header-anchor" href="#sender" aria-label="Permalink to “sender”">​</a></h3><h4 id="get-signature-3" tabindex="-1">Get Signature <a class="header-anchor" href="#get-signature-3" aria-label="Permalink to “Get Signature”">​</a></h4><blockquote><p><strong>get</strong> <strong>sender</strong>(): <code>ChunkSender</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/1e6d90ea19aef765befd07dcc536f23d48c760b1/packages/prismarine/src/network/PlayerSession.ts#L710" target="_blank" rel="noreferrer">prismarine/src/network/PlayerSession.ts:710</a></p><p>The queue the scheduler drains - see ChunkRecipient.</p><h5 id="returns-4" tabindex="-1">Returns <a class="header-anchor" href="#returns-4" aria-label="Permalink to “Returns”">​</a></h5><p><code>ChunkSender</code></p><hr><h3 id="yaw" tabindex="-1">yaw <a class="header-anchor" href="#yaw" aria-label="Permalink to “yaw”">​</a></h3><h4 id="get-signature-4" tabindex="-1">Get Signature <a class="header-anchor" href="#get-signature-4" aria-label="Permalink to “Get Signature”">​</a></h4><blockquote><p><strong>get</strong> <strong>yaw</strong>(): <code>number</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/1e6d90ea19aef765befd07dcc536f23d48c760b1/packages/prismarine/src/network/PlayerSession.ts#L3245" target="_blank" rel="noreferrer">prismarine/src/network/PlayerSession.ts:3245</a></p><h5 id="returns-5" tabindex="-1">Returns <a class="header-anchor" href="#returns-5" aria-label="Permalink to “Returns”">​</a></h5><p><code>number</code></p><h2 id="methods" tabindex="-1">Methods <a class="header-anchor" href="#methods" aria-label="Permalink to “Methods”">​</a></h2><h3 id="abandonrespawnpoint" tabindex="-1">abandonRespawnPoint() <a class="header-anchor" href="#abandonrespawnpoint" aria-label="Permalink to “abandonRespawnPoint()”">​</a></h3><blockquote><p><strong>abandonRespawnPoint</strong>(): <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/1e6d90ea19aef765befd07dcc536f23d48c760b1/packages/prismarine/src/network/PlayerSession.ts#L3585" target="_blank" rel="noreferrer">prismarine/src/network/PlayerSession.ts:3585</a></p><p>Gives up the chunk tickets <a href="#attemptrespawnpoint">attemptRespawnPoint</a> took, for a caller that stops asking before it has the answer, such as a trip out of the End that was dropped. A respawn request of the same player that still waits takes its ticket again at its next attempt.</p><h4 id="returns-6" tabindex="-1">Returns <a class="header-anchor" href="#returns-6" aria-label="Permalink to “Returns”">​</a></h4><p><code>void</code></p><hr><h3 id="addfood" tabindex="-1">addFood() <a class="header-anchor" href="#addfood" aria-label="Permalink to “addFood()”">​</a></h3><blockquote><p><strong>addFood</strong>(<code>food</code>, <code>saturation?</code>): <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/1e6d90ea19aef765befd07dcc536f23d48c760b1/packages/prismarine/src/network/PlayerSession.ts#L3309" target="_blank" rel="noreferrer">prismarine/src/network/PlayerSession.ts:3309</a></p><p>Feeds the player, as eating does.</p><h4 id="parameters-1" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-1" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="food" tabindex="-1">food <a class="header-anchor" href="#food" aria-label="Permalink to “food”">​</a></h5><p><code>number</code></p><h5 id="saturation" tabindex="-1">saturation? <a class="header-anchor" href="#saturation" aria-label="Permalink to “saturation?”">​</a></h5><p><code>number</code> = <code>0</code></p><h4 id="returns-7" tabindex="-1">Returns <a class="header-anchor" href="#returns-7" aria-label="Permalink to “Returns”">​</a></h4><p><code>void</code></p><hr><h3 id="addtoplayerlist" tabindex="-1">addToPlayerList() <a class="header-anchor" href="#addtoplayerlist" aria-label="Permalink to “addToPlayerList()”">​</a></h3><blockquote><p><strong>addToPlayerList</strong>(): <code>Promise</code>&lt;<code>void</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/1e6d90ea19aef765befd07dcc536f23d48c760b1/packages/prismarine/src/network/PlayerSession.ts#L2915" target="_blank" rel="noreferrer">prismarine/src/network/PlayerSession.ts:2915</a></p><p>Adds the client to the player list of every player inside the server and also to the player itself.</p><h4 id="returns-8" tabindex="-1">Returns <a class="header-anchor" href="#returns-8" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>void</code>&gt;</p><hr><h3 id="announcesettings" tabindex="-1">announceSettings() <a class="header-anchor" href="#announcesettings" aria-label="Permalink to “announceSettings()”">​</a></h3><blockquote><p><strong>announceSettings</strong>(): <code>Promise</code>&lt;<code>void</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/1e6d90ea19aef765befd07dcc536f23d48c760b1/packages/prismarine/src/network/PlayerSession.ts#L1229" target="_blank" rel="noreferrer">prismarine/src/network/PlayerSession.ts:1229</a></p><p>Sends this session&#39;s player&#39;s game mode, adventure settings and abilities where each belongs.</p><p>The two halves have different audiences, and sending both to everyone was a bug. <code>UpdateAdventureSettingsPacket</code> carries no target actor - it describes the client receiving it and nothing else - so pushing one player&#39;s settings to every session made a single spectator set <code>worldImmutable</code> on everybody else&#39;s client. It goes to this client alone. <code>UpdateAbilitiesPacket</code> does carry <code>targetActorUniqueId</code>, so it is genuinely about this player and belongs with everyone who can see them.</p><h4 id="returns-9" tabindex="-1">Returns <a class="header-anchor" href="#returns-9" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>void</code>&gt;</p><hr><h3 id="attemptrespawnpoint" tabindex="-1">attemptRespawnPoint() <a class="header-anchor" href="#attemptrespawnpoint" aria-label="Permalink to “attemptRespawnPoint()”">​</a></h3><blockquote><p><strong>attemptRespawnPoint</strong>(): <a href="./../#respawndestination"><code>RespawnDestination</code></a> | <code>undefined</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/1e6d90ea19aef765befd07dcc536f23d48c760b1/packages/prismarine/src/network/PlayerSession.ts#L3575" target="_blank" rel="noreferrer">prismarine/src/network/PlayerSession.ts:3575</a></p><p><a href="#requestrespawnpoint">requestRespawnPoint</a> for a caller that asks again at each input step until it has the answer, such as a trip out of the End. Each attempt that lacks a chunk holds a ticket for it in the player&#39;s name.</p><h4 id="returns-10" tabindex="-1">Returns <a class="header-anchor" href="#returns-10" aria-label="Permalink to “Returns”">​</a></h4><p><a href="./../#respawndestination"><code>RespawnDestination</code></a> | <code>undefined</code></p><p>The destination, or undefined while the search waits for what it lacks.</p><hr><h3 id="beginloadingscreen" tabindex="-1">beginLoadingScreen() <a class="header-anchor" href="#beginloadingscreen" aria-label="Permalink to “beginLoadingScreen()”">​</a></h3><blockquote><p><strong>beginLoadingScreen</strong>(): <code>number</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/1e6d90ea19aef765befd07dcc536f23d48c760b1/packages/prismarine/src/network/PlayerSession.ts#L2308" target="_blank" rel="noreferrer">prismarine/src/network/PlayerSession.ts:2308</a></p><p>Hands out the <code>Loading Screen Id</code> for a <code>ChangeDimensionPacket</code> about to be sent, and remembers it until <a href="#endloadingscreen">PlayerSession.endLoadingScreen</a> hears the client close that screen.</p><h4 id="returns-11" tabindex="-1">Returns <a class="header-anchor" href="#returns-11" aria-label="Permalink to “Returns”">​</a></h4><p><code>number</code></p><p>A uint32 no other open screen on this session uses.</p><hr><h3 id="changeworld" tabindex="-1">changeWorld() <a class="header-anchor" href="#changeworld" aria-label="Permalink to “changeWorld()”">​</a></h3><blockquote><p><strong>changeWorld</strong>(<code>arrival</code>, <code>options?</code>): <code>Promise</code>&lt;<code>void</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/1e6d90ea19aef765befd07dcc536f23d48c760b1/packages/prismarine/src/network/PlayerSession.ts#L2355" target="_blank" rel="noreferrer">prismarine/src/network/PlayerSession.ts:2355</a></p><p>Moves the player to another world and walks the client through the dimension change.</p><p>Server side first: the record is saved to the world being left, stamped with that world&#39;s dimension, the player leaves its roster, the old world&#39;s entities come off the client, the chunk bookkeeping is cleared, the position moves, and the player joins the new roster. Then the wire sequence Dragonfly, Geyser and Nukkit agree on: one <code>ChangeDimension</code> with the target&#39;s Bedrock id, <code>StopSound</code> for everything playing, <code>NetworkChunkPublisherUpdate</code> at the arrival, the server-sent <code>PlayerAction ChangeDimensionAck</code>, the arrival chunks, and <code>PlayStatus PlayerSpawn</code>. The change stays pending, and the client&#39;s <code>PlayerAuthInput</code> is dropped, until the client closes the screen with the id this handed out: see <a href="#completedimensionchange">PlayerSession.completeDimensionChange</a>.</p><p>A client sent <code>ChangeDimension</code> to the dimension it is already in never closes the screen, so a move between two worlds of the same Bedrock id detours through another dimension first.</p><p>A second arrival while a change is pending is held until the client closes the first screen, then carried out; only the latest is kept. A caller whose arrival goes stale while it waits, such as a portal, instead passes <code>whenPending: &#39;drop&#39;</code>: the player is still ticked on the loading screen, and one who arrived inside the exit portal would otherwise be sent back once the 10 tick cooldown ran out, before the client ever closed the first screen. Custom dimension ids are sent after the level announces them in <code>DimensionData</code>.</p><p>Every write is made and every packet queued before this returns, so the input step that runs it waits for nothing. The record&#39;s save is handed to work outside the tick.</p><h4 id="parameters-2" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-2" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="arrival" tabindex="-1">arrival <a class="header-anchor" href="#arrival" aria-label="Permalink to “arrival”">​</a></h5><p><a href="./../#arrival"><code>Arrival</code></a></p><p>The world, feet position and rotation the player lands at.</p><h5 id="options" tabindex="-1">options? <a class="header-anchor" href="#options" aria-label="Permalink to “options?”">​</a></h5><p>What to do with this arrival when a change is already pending.</p><h6 id="whenpending" tabindex="-1">whenPending? <a class="header-anchor" href="#whenpending" aria-label="Permalink to “whenPending?”">​</a></h6><p><code>&quot;queue&quot;</code> | <code>&quot;drop&quot;</code></p><h4 id="returns-12" tabindex="-1">Returns <a class="header-anchor" href="#returns-12" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>void</code>&gt;</p><p>Settles once the transport has framed the packets.</p><hr><h3 id="clearchunks" tabindex="-1">clearChunks() <a class="header-anchor" href="#clearchunks" aria-label="Permalink to “clearChunks()”">​</a></h3><blockquote><p><strong>clearChunks</strong>(): <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/1e6d90ea19aef765befd07dcc536f23d48c760b1/packages/prismarine/src/network/PlayerSession.ts#L1423" target="_blank" rel="noreferrer">prismarine/src/network/PlayerSession.ts:1423</a></p><p>Clear the currently loaded and loading chunks.</p><h4 id="returns-13" tabindex="-1">Returns <a class="header-anchor" href="#returns-13" aria-label="Permalink to “Returns”">​</a></h4><p><code>void</code></p><h4 id="remarks" tabindex="-1">Remarks <a class="header-anchor" href="#remarks" aria-label="Permalink to “Remarks”">​</a></h4><p>Usually used for changing dimension, world, etc.</p><p>Everything in flight goes with them. The two sets are only the bookkeeping; the queue of coordinates still to send and the chunks already produced but not yet dispatched are the actual work, and they belong to the world being left. Left in place, a dimension change sent the old world&#39;s terrain into the new one, and resolved the leftover coordinates against a world where they mean somewhere else entirely.</p><hr><h3 id="closewindow" tabindex="-1">closeWindow() <a class="header-anchor" href="#closewindow" aria-label="Permalink to “closeWindow()”">​</a></h3><blockquote><p><strong>closeWindow</strong>(<code>windowId</code>): <code>boolean</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/1e6d90ea19aef765befd07dcc536f23d48c760b1/packages/prismarine/src/network/PlayerSession.ts#L1821" target="_blank" rel="noreferrer">prismarine/src/network/PlayerSession.ts:1821</a></p><p>Forgets a window the client reports closed.</p><p>The docs have the server delete its container manager when the client&#39;s <code>ContainerClose</code> arrives, before answering it. Only a window this session opened can be closed here; any other id is left alone and reported through the return value so the handler can log it.</p><h4 id="parameters-3" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-3" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="windowid" tabindex="-1">windowId <a class="header-anchor" href="#windowid" aria-label="Permalink to “windowId”">​</a></h5><p><code>number</code></p><p>the <code>Container Id</code> the client sent.</p><h4 id="returns-14" tabindex="-1">Returns <a class="header-anchor" href="#returns-14" aria-label="Permalink to “Returns”">​</a></h4><p><code>boolean</code></p><p>whether a window with that id was open.</p><hr><h3 id="completecredits" tabindex="-1">completeCredits() <a class="header-anchor" href="#completecredits" aria-label="Permalink to “completeCredits()”">​</a></h3><blockquote><p><strong>completeCredits</strong>(): <code>boolean</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/1e6d90ea19aef765befd07dcc536f23d48c760b1/packages/prismarine/src/network/PlayerSession.ts#L2575" target="_blank" rel="noreferrer">prismarine/src/network/PlayerSession.ts:2575</a></p><p>Finishes held credits: the full dimension change sequence to the held arrival, sent as a respawn, which is how Java&#39;s <code>PlayerList.respawn(player, true, ...)</code> answers the credits. Called by <code>ShowCreditsHandler</code> when the client reports the credits finished.</p><p>The change is a message: it runs at the next input step through <code>DimensionTravel.move</code>, so the handler that reports the finish waits for nothing.</p><h4 id="returns-15" tabindex="-1">Returns <a class="header-anchor" href="#returns-15" aria-label="Permalink to “Returns”">​</a></h4><p><code>boolean</code></p><p>Whether credits were pending. A finish with none pending changes nothing.</p><hr><h3 id="completedimensionchange" tabindex="-1">completeDimensionChange() <a class="header-anchor" href="#completedimensionchange" aria-label="Permalink to “completeDimensionChange()”">​</a></h3><blockquote><p><strong>completeDimensionChange</strong>(<code>loadingScreenId</code>): <code>boolean</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/1e6d90ea19aef765befd07dcc536f23d48c760b1/packages/prismarine/src/network/PlayerSession.ts#L2644" target="_blank" rel="noreferrer">prismarine/src/network/PlayerSession.ts:2644</a></p><p>Finishes a pending world change once the client reports its loading screen closed.</p><p>Teleports the client to the exact arrival position, re-sends the attributes and the inventory, which a dimension change is not known to keep, tells the client where its spawn point is from the new dimension, and raises the changed dimension advancement hook, in that order. A change held while this one was pending is filed last, as a message the next input step carries out. Called by <code>ServerboundLoadingScreenHandler</code> in its unit, and by the tick for a client that never closed the screen. Every packet is queued before this returns.</p><h4 id="parameters-4" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-4" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="loadingscreenid" tabindex="-1">loadingScreenId <a class="header-anchor" href="#loadingscreenid" aria-label="Permalink to “loadingScreenId”">​</a></h5><p><code>number</code></p><p>The id the client&#39;s <code>EndLoadingScreen</code> carried.</p><h4 id="returns-16" tabindex="-1">Returns <a class="header-anchor" href="#returns-16" aria-label="Permalink to “Returns”">​</a></h4><p><code>boolean</code></p><p>Whether a change was pending under that id. Any other id changes nothing.</p><hr><h3 id="completespawn" tabindex="-1">completeSpawn() <a class="header-anchor" href="#completespawn" aria-label="Permalink to “completeSpawn()”">​</a></h3><blockquote><p><strong>completeSpawn</strong>(): <code>Promise</code>&lt;<code>void</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/1e6d90ea19aef765befd07dcc536f23d48c760b1/packages/prismarine/src/network/PlayerSession.ts#L2156" target="_blank" rel="noreferrer">prismarine/src/network/PlayerSession.ts:2156</a></p><p>Finishes bringing this session&#39;s player into the game: position, gamemode, inventory, settings, and the attributes, metadata and status effects the spawning client threw away.</p><h4 id="returns-17" tabindex="-1">Returns <a class="header-anchor" href="#returns-17" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>void</code>&gt;</p><h4 id="remarks-1" tabindex="-1">Remarks <a class="header-anchor" href="#remarks-1" aria-label="Permalink to “Remarks”">​</a></h4><p>Named apart from <code>StorePlayerActor.spawnTo</code> on purpose. This used to be called <code>sendSpawn</code>, overriding the entity method of that name with a different signature and an unrelated meaning - one is &quot;put me into the world&quot;, the other is &quot;show me to somebody&quot;. Adding a player to a world therefore ran this by accident.</p><hr><h3 id="considerentity" tabindex="-1">considerEntity() <a class="header-anchor" href="#considerentity" aria-label="Permalink to “considerEntity()”">​</a></h3><blockquote><p><strong>considerEntity</strong>(<code>entity</code>): <code>Promise</code>&lt;<code>void</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/1e6d90ea19aef765befd07dcc536f23d48c760b1/packages/prismarine/src/network/PlayerSession.ts#L1021" target="_blank" rel="noreferrer">prismarine/src/network/PlayerSession.ts:1021</a></p><p>Shows one entity to this client, if it is close enough and not already shown.</p><p>The single-entity path, for something that has just entered the world rather than a whole pass over everything in it.</p><h4 id="parameters-5" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-5" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="entity" tabindex="-1">entity <a class="header-anchor" href="#entity" aria-label="Permalink to “entity”">​</a></h5><p><code>ShownEntity</code></p><p>The entity to consider.</p><h4 id="returns-18" tabindex="-1">Returns <a class="header-anchor" href="#returns-18" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>void</code>&gt;</p><hr><h3 id="deliver" tabindex="-1">deliver() <a class="header-anchor" href="#deliver" aria-label="Permalink to “deliver()”">​</a></h3><blockquote><p><strong>deliver</strong>(<code>x</code>, <code>z</code>): <code>Promise</code>&lt;<code>void</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/1e6d90ea19aef765befd07dcc536f23d48c760b1/packages/prismarine/src/network/PlayerSession.ts#L723" target="_blank" rel="noreferrer">prismarine/src/network/PlayerSession.ts:723</a></p><p>Produces one chunk and queues it for the next batch. Called only by the scheduler.</p><p>The scheduler takes a coordinate off the queue before calling this, so a failure here has to put the bookkeeping back: <code>loadingChunks</code> is what stops <code>needNewChunks</code> from asking for the same chunk twice, and leaving the hash in it after nothing was sent means that chunk is never requested again - a permanent hole in the player&#39;s world for as long as they stay in range of it.</p><h4 id="parameters-6" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-6" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="x" tabindex="-1">x <a class="header-anchor" href="#x" aria-label="Permalink to “x”">​</a></h5><p><code>number</code></p><h5 id="z" tabindex="-1">z <a class="header-anchor" href="#z" aria-label="Permalink to “z”">​</a></h5><p><code>number</code></p><h4 id="returns-19" tabindex="-1">Returns <a class="header-anchor" href="#returns-19" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>void</code>&gt;</p><hr><h3 id="despawnalltrackedentities" tabindex="-1">despawnAllTrackedEntities() <a class="header-anchor" href="#despawnalltrackedentities" aria-label="Permalink to “despawnAllTrackedEntities()”">​</a></h3><blockquote><p><strong>despawnAllTrackedEntities</strong>(): <code>Promise</code>&lt;<code>void</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/1e6d90ea19aef765befd07dcc536f23d48c760b1/packages/prismarine/src/network/PlayerSession.ts#L1051" target="_blank" rel="noreferrer">prismarine/src/network/PlayerSession.ts:1051</a></p><p>Hides every tracked entity from this client and forgets them all.</p><p>For a world change. A dimension change does not make the client drop what it holds, so the mobs of the world being left stayed on screen in the new one. Not routed through <a href="#reconciletrackedentities">PlayerSession.reconcileTrackedEntities</a>: that returns early while another pass runs, and a world change cannot be skipped.</p><h4 id="returns-20" tabindex="-1">Returns <a class="header-anchor" href="#returns-20" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>void</code>&gt;</p><hr><h3 id="dropentity" tabindex="-1">dropEntity() <a class="header-anchor" href="#dropentity" aria-label="Permalink to “dropEntity()”">​</a></h3><blockquote><p><strong>dropEntity</strong>(<code>entity</code>): <code>Promise</code>&lt;<code>void</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/1e6d90ea19aef765befd07dcc536f23d48c760b1/packages/prismarine/src/network/PlayerSession.ts#L1038" target="_blank" rel="noreferrer">prismarine/src/network/PlayerSession.ts:1038</a></p><p>Hides one entity from this client if it is showing, and forgets it either way.</p><p>Unconditional forgetting matters: a stale id left behind would make the tracker believe the client still has an entity it does not, and block it from ever being sent again.</p><h4 id="parameters-7" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-7" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="entity-1" tabindex="-1">entity <a class="header-anchor" href="#entity-1" aria-label="Permalink to “entity”">​</a></h5><p><code>Pick</code>&lt;<code>ShownActor</code>, <code>&quot;getRuntimeId&quot;</code>&gt;</p><p>The entity that is going away.</p><h4 id="returns-21" tabindex="-1">Returns <a class="header-anchor" href="#returns-21" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>void</code>&gt;</p><hr><h3 id="endloadingscreen" tabindex="-1">endLoadingScreen() <a class="header-anchor" href="#endloadingscreen" aria-label="Permalink to “endLoadingScreen()”">​</a></h3><blockquote><p><strong>endLoadingScreen</strong>(<code>id</code>): <code>boolean</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/1e6d90ea19aef765befd07dcc536f23d48c760b1/packages/prismarine/src/network/PlayerSession.ts#L2320" target="_blank" rel="noreferrer">prismarine/src/network/PlayerSession.ts:2320</a></p><p>Records that the client closed a loading screen.</p><h4 id="parameters-8" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-8" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="id" tabindex="-1">id <a class="header-anchor" href="#id" aria-label="Permalink to “id”">​</a></h5><p><code>number</code></p><p>The <code>Loading Screen Id</code> from the client&#39;s <code>ServerboundLoadingScreenPacket</code>.</p><h4 id="returns-22" tabindex="-1">Returns <a class="header-anchor" href="#returns-22" aria-label="Permalink to “Returns”">​</a></h4><p><code>boolean</code></p><p>Whether the id belonged to a screen this session had opened and not yet closed.</p><hr><h3 id="flush" tabindex="-1">flush() <a class="header-anchor" href="#flush" aria-label="Permalink to “flush()”">​</a></h3><blockquote><p><strong>flush</strong>(): <code>Promise</code>&lt;<code>void</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/1e6d90ea19aef765befd07dcc536f23d48c760b1/packages/prismarine/src/network/PlayerSession.ts#L1061" target="_blank" rel="noreferrer">prismarine/src/network/PlayerSession.ts:1061</a></p><p>Sends what has been produced but not yet dispatched.</p><p>Called by the scheduler at the end of its pass, so a partial batch does not sit until the next tick.</p><h4 id="returns-23" tabindex="-1">Returns <a class="header-anchor" href="#returns-23" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>void</code>&gt;</p><hr><h3 id="flushqueuedmoves" tabindex="-1">flushQueuedMoves() <a class="header-anchor" href="#flushqueuedmoves" aria-label="Permalink to “flushQueuedMoves()”">​</a></h3><blockquote><p><strong>flushQueuedMoves</strong>(): <code>Promise</code>&lt;<code>void</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/1e6d90ea19aef765befd07dcc536f23d48c760b1/packages/prismarine/src/network/PlayerSession.ts#L3088" target="_blank" rel="noreferrer">prismarine/src/network/PlayerSession.ts:3088</a></p><p>Sends this tick&#39;s movement as one batch.</p><p>Called once per world tick, after every entity has had its update.</p><h4 id="returns-24" tabindex="-1">Returns <a class="header-anchor" href="#returns-24" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>void</code>&gt;</p><p>Resolves once the batch has been framed.</p><hr><h3 id="getactor" tabindex="-1">getActor() <a class="header-anchor" href="#getactor" aria-label="Permalink to “getActor()”">​</a></h3><blockquote><p><strong>getActor</strong>(): <code>StorePlayerActor</code> | <code>undefined</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/1e6d90ea19aef765befd07dcc536f23d48c760b1/packages/prismarine/src/network/PlayerSession.ts#L3179" target="_blank" rel="noreferrer">prismarine/src/network/PlayerSession.ts:3179</a></p><p>The player&#39;s actor while its entity is in the store of its world: what entity code is handed in the player&#39;s place, such as a blow&#39;s attacker, the portal touch and the entity events. Undefined from the login to the spawn and between two worlds, when nothing can reach the player.</p><h4 id="returns-25" tabindex="-1">Returns <a class="header-anchor" href="#returns-25" aria-label="Permalink to “Returns”">​</a></h4><p><code>StorePlayerActor</code> | <code>undefined</code></p><hr><h3 id="getbox" tabindex="-1">getBox() <a class="header-anchor" href="#getbox" aria-label="Permalink to “getBox()”">​</a></h3><blockquote><p><strong>getBox</strong>(): <code>EntityBox</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/1e6d90ea19aef765befd07dcc536f23d48c760b1/packages/prismarine/src/network/PlayerSession.ts#L3202" target="_blank" rel="noreferrer">prismarine/src/network/PlayerSession.ts:3202</a></p><p>The box the player&#39;s body takes up, from the type&#39;s collision box.</p><h4 id="returns-26" tabindex="-1">Returns <a class="header-anchor" href="#returns-26" aria-label="Permalink to “Returns”">​</a></h4><p><code>EntityBox</code></p><hr><h3 id="getclientcacheenabled" tabindex="-1">getClientCacheEnabled() <a class="header-anchor" href="#getclientcacheenabled" aria-label="Permalink to “getClientCacheEnabled()”">​</a></h3><blockquote><p><strong>getClientCacheEnabled</strong>(): <code>boolean</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/1e6d90ea19aef765befd07dcc536f23d48c760b1/packages/prismarine/src/network/PlayerSession.ts#L755" target="_blank" rel="noreferrer">prismarine/src/network/PlayerSession.ts:755</a></p><p>Whether this session will use cached blobs in request-mode subchunk responses.</p><h4 id="returns-27" tabindex="-1">Returns <a class="header-anchor" href="#returns-27" aria-label="Permalink to “Returns”">​</a></h4><p><code>boolean</code></p><hr><h3 id="getconnection" tabindex="-1">getConnection() <a class="header-anchor" href="#getconnection" aria-label="Permalink to “getConnection()”">​</a></h3><blockquote><p><strong>getConnection</strong>(): <code>ClientConnection</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/1e6d90ea19aef765befd07dcc536f23d48c760b1/packages/prismarine/src/network/PlayerSession.ts#L3122" target="_blank" rel="noreferrer">prismarine/src/network/PlayerSession.ts:3122</a></p><h4 id="returns-28" tabindex="-1">Returns <a class="header-anchor" href="#returns-28" aria-label="Permalink to “Returns”">​</a></h4><p><code>ClientConnection</code></p><hr><h3 id="getequipment" tabindex="-1">getEquipment() <a class="header-anchor" href="#getequipment" aria-label="Permalink to “getEquipment()”">​</a></h3><blockquote><p><strong>getEquipment</strong>(): <code>ViewableEquipment</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/1e6d90ea19aef765befd07dcc536f23d48c760b1/packages/prismarine/src/network/PlayerSession.ts#L3269" target="_blank" rel="noreferrer">prismarine/src/network/PlayerSession.ts:3269</a></p><p>What the player wears and holds.</p><h4 id="returns-29" tabindex="-1">Returns <a class="header-anchor" href="#returns-29" aria-label="Permalink to “Returns”">​</a></h4><p><code>ViewableEquipment</code></p><hr><h3 id="getexperience" tabindex="-1">getExperience() <a class="header-anchor" href="#getexperience" aria-label="Permalink to “getExperience()”">​</a></h3><blockquote><p><strong>getExperience</strong>(): <code>ExperienceHolder</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/1e6d90ea19aef765befd07dcc536f23d48c760b1/packages/prismarine/src/network/PlayerSession.ts#L3319" target="_blank" rel="noreferrer">prismarine/src/network/PlayerSession.ts:3319</a></p><p>The experience, written through logged setters.</p><h4 id="returns-30" tabindex="-1">Returns <a class="header-anchor" href="#returns-30" aria-label="Permalink to “Returns”">​</a></h4><p><code>ExperienceHolder</code></p><hr><h3 id="getfalldistance" tabindex="-1">getFallDistance() <a class="header-anchor" href="#getfalldistance" aria-label="Permalink to “getFallDistance()”">​</a></h3><blockquote><p><strong>getFallDistance</strong>(): <code>number</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/1e6d90ea19aef765befd07dcc536f23d48c760b1/packages/prismarine/src/network/PlayerSession.ts#L3314" target="_blank" rel="noreferrer">prismarine/src/network/PlayerSession.ts:3314</a></p><p>How far the player has fallen since it was last supported.</p><h4 id="returns-31" tabindex="-1">Returns <a class="header-anchor" href="#returns-31" aria-label="Permalink to “Returns”">​</a></h4><p><code>number</code></p><hr><h3 id="getfeety" tabindex="-1">getFeetY() <a class="header-anchor" href="#getfeety" aria-label="Permalink to “getFeetY()”">​</a></h3><blockquote><p><strong>getFeetY</strong>(): <code>number</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/1e6d90ea19aef765befd07dcc536f23d48c760b1/packages/prismarine/src/network/PlayerSession.ts#L3241" target="_blank" rel="noreferrer">prismarine/src/network/PlayerSession.ts:3241</a></p><p>The bottom of the player&#39;s body.</p><h4 id="returns-32" tabindex="-1">Returns <a class="header-anchor" href="#returns-32" aria-label="Permalink to “Returns”">​</a></h4><p><code>number</code></p><hr><h3 id="getfood" tabindex="-1">getFood() <a class="header-anchor" href="#getfood" aria-label="Permalink to “getFood()”">​</a></h3><blockquote><p><strong>getFood</strong>(): <code>number</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/1e6d90ea19aef765befd07dcc536f23d48c760b1/packages/prismarine/src/network/PlayerSession.ts#L3299" target="_blank" rel="noreferrer">prismarine/src/network/PlayerSession.ts:3299</a></p><p>Food, out of 20.</p><h4 id="returns-33" tabindex="-1">Returns <a class="header-anchor" href="#returns-33" aria-label="Permalink to “Returns”">​</a></h4><p><code>number</code></p><hr><h3 id="getformattedusername" tabindex="-1">getFormattedUsername() <a class="header-anchor" href="#getformattedusername" aria-label="Permalink to “getFormattedUsername()”">​</a></h3><blockquote><p><strong>getFormattedUsername</strong>(): <code>string</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/1e6d90ea19aef765befd07dcc536f23d48c760b1/packages/prismarine/src/network/PlayerSession.ts#L3344" target="_blank" rel="noreferrer">prismarine/src/network/PlayerSession.ts:3344</a></p><p>The name as a chat line attributes it.</p><h4 id="returns-34" tabindex="-1">Returns <a class="header-anchor" href="#returns-34" aria-label="Permalink to “Returns”">​</a></h4><p><code>string</code></p><hr><h3 id="getinventory" tabindex="-1">getInventory() <a class="header-anchor" href="#getinventory" aria-label="Permalink to “getInventory()”">​</a></h3><blockquote><p><strong>getInventory</strong>(): <code>HumanInventory</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/1e6d90ea19aef765befd07dcc536f23d48c760b1/packages/prismarine/src/network/PlayerSession.ts#L3264" target="_blank" rel="noreferrer">prismarine/src/network/PlayerSession.ts:3264</a></p><p>What the player carries.</p><h4 id="returns-35" tabindex="-1">Returns <a class="header-anchor" href="#returns-35" aria-label="Permalink to “Returns”">​</a></h4><p><code>HumanInventory</code></p><hr><h3 id="getjoinspawn" tabindex="-1">getJoinSpawn() <a class="header-anchor" href="#getjoinspawn" aria-label="Permalink to “getJoinSpawn()”">​</a></h3><blockquote><p><strong>getJoinSpawn</strong>(): <code>PlayerSpawn</code> | <code>null</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/1e6d90ea19aef765befd07dcc536f23d48c760b1/packages/prismarine/src/network/PlayerSession.ts#L2097" target="_blank" rel="noreferrer">prismarine/src/network/PlayerSession.ts:2097</a></p><p>Where the player was placed on joining, or null when they came back to a saved position.</p><h4 id="returns-36" tabindex="-1">Returns <a class="header-anchor" href="#returns-36" aria-label="Permalink to “Returns”">​</a></h4><p><code>PlayerSpawn</code> | <code>null</code></p><hr><h3 id="getname" tabindex="-1">getName() <a class="header-anchor" href="#getname" aria-label="Permalink to “getName()”">​</a></h3><blockquote><p><strong>getName</strong>(): <code>string</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/1e6d90ea19aef765befd07dcc536f23d48c760b1/packages/prismarine/src/network/PlayerSession.ts#L3339" target="_blank" rel="noreferrer">prismarine/src/network/PlayerSession.ts:3339</a></p><p>The name the player logged in with.</p><h4 id="returns-37" tabindex="-1">Returns <a class="header-anchor" href="#returns-37" aria-label="Permalink to “Returns”">​</a></h4><p><code>string</code></p><hr><h3 id="getopenblockcontainer" tabindex="-1">getOpenBlockContainer() <a class="header-anchor" href="#getopenblockcontainer" aria-label="Permalink to “getOpenBlockContainer()”">​</a></h3><blockquote><p><strong>getOpenBlockContainer</strong>(): <a href="./../#openblockcontainer"><code>OpenBlockContainer</code></a> | <code>undefined</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/1e6d90ea19aef765befd07dcc536f23d48c760b1/packages/prismarine/src/network/PlayerSession.ts#L1772" target="_blank" rel="noreferrer">prismarine/src/network/PlayerSession.ts:1772</a></p><p>The block container this session has open, or undefined for none.</p><h4 id="returns-38" tabindex="-1">Returns <a class="header-anchor" href="#returns-38" aria-label="Permalink to “Returns”">​</a></h4><p><a href="./../#openblockcontainer"><code>OpenBlockContainer</code></a> | <code>undefined</code></p><hr><h3 id="getpermissions" tabindex="-1">getPermissions() <a class="header-anchor" href="#getpermissions" aria-label="Permalink to “getPermissions()”">​</a></h3><blockquote><p><strong>getPermissions</strong>(): <code>string</code>[]</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/1e6d90ea19aef765befd07dcc536f23d48c760b1/packages/prismarine/src/network/PlayerSession.ts#L3357" target="_blank" rel="noreferrer">prismarine/src/network/PlayerSession.ts:3357</a></p><p>The permissions the player holds, read from the permission manager on every call so a revoked operator status or grant applies at once.</p><h4 id="returns-39" tabindex="-1">Returns <a class="header-anchor" href="#returns-39" aria-label="Permalink to “Returns”">​</a></h4><p><code>string</code>[]</p><hr><h3 id="getplayer" tabindex="-1">getPlayer() <a class="header-anchor" href="#getplayer" aria-label="Permalink to “getPlayer()”">​</a></h3><blockquote><p><strong>getPlayer</strong>(): <code>StorePlayer</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/1e6d90ea19aef765befd07dcc536f23d48c760b1/packages/prismarine/src/network/PlayerSession.ts#L3135" target="_blank" rel="noreferrer">prismarine/src/network/PlayerSession.ts:3135</a></p><p>The player this session speaks for, found by its entity id.</p><p>The one way from a session to its player&#39;s state, the store player the server&#39;s directory files by that id. Code that needs only the id, the name or the key reads <a href="#runtimeid">PlayerSession.runtimeId</a> or <a href="#identity">PlayerSession.identity</a> instead.</p><h4 id="returns-40" tabindex="-1">Returns <a class="header-anchor" href="#returns-40" aria-label="Permalink to “Returns”">​</a></h4><p><code>StorePlayer</code></p><p>The player.</p><h4 id="throws" tabindex="-1">Throws <a class="header-anchor" href="#throws" aria-label="Permalink to “Throws”">​</a></h4><p>Once <a href="#disable">PlayerSession.disable</a> has forgotten the player.</p><hr><h3 id="getposition" tabindex="-1">getPosition() <a class="header-anchor" href="#getposition" aria-label="Permalink to “getPosition()”">​</a></h3><blockquote><p><strong>getPosition</strong>(): <a href="./../../../../math/classes/Vector3.html"><code>Vector3</code></a></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/1e6d90ea19aef765befd07dcc536f23d48c760b1/packages/prismarine/src/network/PlayerSession.ts#L3236" target="_blank" rel="noreferrer">prismarine/src/network/PlayerSession.ts:3236</a></p><p>Where the player&#39;s eyes are, as its client reports them.</p><h4 id="returns-41" tabindex="-1">Returns <a class="header-anchor" href="#returns-41" aria-label="Permalink to “Returns”">​</a></h4><p><a href="./../../../../math/classes/Vector3.html"><code>Vector3</code></a></p><hr><h3 id="getruntimeid" tabindex="-1">getRuntimeId() <a class="header-anchor" href="#getruntimeid" aria-label="Permalink to “getRuntimeId()”">​</a></h3><blockquote><p><strong>getRuntimeId</strong>(): <code>bigint</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/1e6d90ea19aef765befd07dcc536f23d48c760b1/packages/prismarine/src/network/PlayerSession.ts#L3221" target="_blank" rel="noreferrer">prismarine/src/network/PlayerSession.ts:3221</a></p><p>The player&#39;s entity id.</p><h4 id="returns-42" tabindex="-1">Returns <a class="header-anchor" href="#returns-42" aria-label="Permalink to “Returns”">​</a></h4><p><code>bigint</code></p><hr><h3 id="getsaturation" tabindex="-1">getSaturation() <a class="header-anchor" href="#getsaturation" aria-label="Permalink to “getSaturation()”">​</a></h3><blockquote><p><strong>getSaturation</strong>(): <code>number</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/1e6d90ea19aef765befd07dcc536f23d48c760b1/packages/prismarine/src/network/PlayerSession.ts#L3304" target="_blank" rel="noreferrer">prismarine/src/network/PlayerSession.ts:3304</a></p><p>The hidden buffer spent before food.</p><h4 id="returns-43" tabindex="-1">Returns <a class="header-anchor" href="#returns-43" aria-label="Permalink to “Returns”">​</a></h4><p><code>number</code></p><hr><h3 id="getserver" tabindex="-1">getServer() <a class="header-anchor" href="#getserver" aria-label="Permalink to “getServer()”">​</a></h3><blockquote><p><strong>getServer</strong>(): <a href="./../../../Server/classes/Server.html"><code>Server</code></a></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/1e6d90ea19aef765befd07dcc536f23d48c760b1/packages/prismarine/src/network/PlayerSession.ts#L3207" target="_blank" rel="noreferrer">prismarine/src/network/PlayerSession.ts:3207</a></p><p>The server this session belongs to.</p><h4 id="returns-44" tabindex="-1">Returns <a class="header-anchor" href="#returns-44" aria-label="Permalink to “Returns”">​</a></h4><p><a href="./../../../Server/classes/Server.html"><code>Server</code></a></p><hr><h3 id="getspawnpoint" tabindex="-1">getSpawnPoint() <a class="header-anchor" href="#getspawnpoint" aria-label="Permalink to “getSpawnPoint()”">​</a></h3><blockquote><p><strong>getSpawnPoint</strong>(): <code>StoredSpawnPoint</code> | <code>undefined</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/1e6d90ea19aef765befd07dcc536f23d48c760b1/packages/prismarine/src/network/PlayerSession.ts#L3329" target="_blank" rel="noreferrer">prismarine/src/network/PlayerSession.ts:3329</a></p><p>The player&#39;s own spawn point, or undefined for the world spawn.</p><h4 id="returns-45" tabindex="-1">Returns <a class="header-anchor" href="#returns-45" aria-label="Permalink to “Returns”">​</a></h4><p><code>StoredSpawnPoint</code> | <code>undefined</code></p><hr><h3 id="getstatuseffects" tabindex="-1">getStatusEffects() <a class="header-anchor" href="#getstatuseffects" aria-label="Permalink to “getStatusEffects()”">​</a></h3><blockquote><p><strong>getStatusEffects</strong>(): readonly <code>StatusEffect</code>[]</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/1e6d90ea19aef765befd07dcc536f23d48c760b1/packages/prismarine/src/network/PlayerSession.ts#L3274" target="_blank" rel="noreferrer">prismarine/src/network/PlayerSession.ts:3274</a></p><p>The status effects on the player.</p><h4 id="returns-46" tabindex="-1">Returns <a class="header-anchor" href="#returns-46" aria-label="Permalink to “Returns”">​</a></h4><p>readonly <code>StatusEffect</code>[]</p><hr><h3 id="gettype" tabindex="-1">getType() <a class="header-anchor" href="#gettype" aria-label="Permalink to “getType()”">​</a></h3><blockquote><p><strong>getType</strong>(): <code>string</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/1e6d90ea19aef765befd07dcc536f23d48c760b1/packages/prismarine/src/network/PlayerSession.ts#L3226" target="_blank" rel="noreferrer">prismarine/src/network/PlayerSession.ts:3226</a></p><p>The type of the player&#39;s entity, <code>minecraft:player</code>.</p><h4 id="returns-47" tabindex="-1">Returns <a class="header-anchor" href="#returns-47" aria-label="Permalink to “Returns”">​</a></h4><p><code>string</code></p><hr><h3 id="getviewdistance" tabindex="-1">getViewDistance() <a class="header-anchor" href="#getviewdistance" aria-label="Permalink to “getViewDistance()”">​</a></h3><blockquote><p><strong>getViewDistance</strong>(): <code>number</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/1e6d90ea19aef765befd07dcc536f23d48c760b1/packages/prismarine/src/network/PlayerSession.ts#L2090" target="_blank" rel="noreferrer">prismarine/src/network/PlayerSession.ts:2090</a></p><p>The chunk radius this client sees, as it asked for it, in chunks.</p><h4 id="returns-48" tabindex="-1">Returns <a class="header-anchor" href="#returns-48" aria-label="Permalink to “Returns”">​</a></h4><p><code>number</code></p><p>The radius, or zero until the client&#39;s first <code>RequestChunkRadius</code>.</p><hr><h3 id="getviewposition" tabindex="-1">getViewPosition() <a class="header-anchor" href="#getviewposition" aria-label="Permalink to “getViewPosition()”">​</a></h3><blockquote><p><strong>getViewPosition</strong>(): <a href="./../../../../math/classes/Vector3.html"><code>Vector3</code></a></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/1e6d90ea19aef765befd07dcc536f23d48c760b1/packages/prismarine/src/network/PlayerSession.ts#L2082" target="_blank" rel="noreferrer">prismarine/src/network/PlayerSession.ts:2082</a></p><p>Where this client sees the world from: its player&#39;s eyes, the point chunk streaming, entity tracking and a world&#39;s broadcasts measure from.</p><h4 id="returns-49" tabindex="-1">Returns <a class="header-anchor" href="#returns-49" aria-label="Permalink to “Returns”">​</a></h4><p><a href="./../../../../math/classes/Vector3.html"><code>Vector3</code></a></p><p>The position.</p><hr><h3 id="getworld" tabindex="-1">getWorld() <a class="header-anchor" href="#getworld" aria-label="Permalink to “getWorld()”">​</a></h3><blockquote><p><strong>getWorld</strong>(): <a href="./../../../world/World/classes/World.html"><code>World</code></a></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/1e6d90ea19aef765befd07dcc536f23d48c760b1/packages/prismarine/src/network/PlayerSession.ts#L2073" target="_blank" rel="noreferrer">prismarine/src/network/PlayerSession.ts:2073</a></p><p>The world this session&#39;s player is in, which is the world its chunks are streamed from.</p><p>During a dimension change it is the destination from the moment the player moves, while the client may still be on its loading screen.</p><h4 id="returns-50" tabindex="-1">Returns <a class="header-anchor" href="#returns-50" aria-label="Permalink to “Returns”">​</a></h4><p><a href="./../../../world/World/classes/World.html"><code>World</code></a></p><p>The world.</p><hr><h3 id="getxuid" tabindex="-1">getXUID() <a class="header-anchor" href="#getxuid" aria-label="Permalink to “getXUID()”">​</a></h3><blockquote><p><strong>getXUID</strong>(): <code>string</code> | <code>null</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/1e6d90ea19aef765befd07dcc536f23d48c760b1/packages/prismarine/src/network/PlayerSession.ts#L3231" target="_blank" rel="noreferrer">prismarine/src/network/PlayerSession.ts:3231</a></p><p>The XUID the login carried, or null when it carried none.</p><h4 id="returns-51" tabindex="-1">Returns <a class="header-anchor" href="#returns-51" aria-label="Permalink to “Returns”">​</a></h4><p><code>string</code> | <code>null</code></p><hr><h3 id="handleclientcacheblobstatus" tabindex="-1">handleClientCacheBlobStatus() <a class="header-anchor" href="#handleclientcacheblobstatus" aria-label="Permalink to “handleClientCacheBlobStatus()”">​</a></h3><blockquote><p><strong>handleClientCacheBlobStatus</strong>(<code>packet</code>): <code>Promise</code>&lt;<code>number</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/1e6d90ea19aef765befd07dcc536f23d48c760b1/packages/prismarine/src/network/PlayerSession.ts#L768" target="_blank" rel="noreferrer">prismarine/src/network/PlayerSession.ts:768</a></p><p>Responds to requested blob misses and applies the client&#39;s acknowledgements.</p><p>Every status is answered, with an empty <code>ClientCacheMissResponse</code> when the client missed nothing. Bedrock Dedicated Server 1.26.60 does the same, 105 answers to 105 statuses in the capture docs/research/sub-chunk-requests-and-blob-cache.md describes. Do not skip the empty one to save a packet: the answer is what closes the client&#39;s cache transaction.</p><h4 id="parameters-9" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-9" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="packet" tabindex="-1">packet <a class="header-anchor" href="#packet" aria-label="Permalink to “packet”">​</a></h5><p><a href="./../../../../protocol/classes/ClientCacheBlobStatusPacket.html"><code>ClientCacheBlobStatusPacket</code></a></p><h4 id="returns-52" tabindex="-1">Returns <a class="header-anchor" href="#returns-52" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>number</code>&gt;</p><p>How many blobs went out.</p><hr><h3 id="handlesubchunkrequest" tabindex="-1">handleSubChunkRequest() <a class="header-anchor" href="#handlesubchunkrequest" aria-label="Permalink to “handleSubChunkRequest()”">​</a></h3><blockquote><p><strong>handleSubChunkRequest</strong>(<code>packet</code>): <code>Promise</code>&lt;<code>number</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/1e6d90ea19aef765befd07dcc536f23d48c760b1/packages/prismarine/src/network/PlayerSession.ts#L796" target="_blank" rel="noreferrer">prismarine/src/network/PlayerSession.ts:796</a></p><p>Answers requested sections with their bytes, block entities, heightmaps, and cache ids.</p><p>The shape of each entry follows a capture of Bedrock Dedicated Server 1.26.60 answering a retail client, recorded in docs/research/sub-chunk-requests-and-blob-cache.md. With the client&#39;s blob cache on:</p><ul><li>A section with blocks carries the hash of its terrain and a payload that is present even when empty. The payload holds the section&#39;s block entities only.</li><li>An all-air section carries neither payload nor hash.</li><li>The answer is the same whether or not the client has confirmed the blob before.</li></ul><p>These look like things to simplify, such as dropping an empty payload or sending the terrain inline to save a round trip. A retail client leaves with a bad packet error (<code>ClientDisconnection-90</code>) on either, so change them only against a new capture.</p><h4 id="parameters-10" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-10" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="packet-1" tabindex="-1">packet <a class="header-anchor" href="#packet-1" aria-label="Permalink to “packet”">​</a></h5><p><a href="./../../../../protocol/classes/SubChunkRequestPacket.html"><code>SubChunkRequestPacket</code></a></p><p>The requested chunk columns and absolute subchunk center.</p><h4 id="returns-53" tabindex="-1">Returns <a class="header-anchor" href="#returns-53" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>number</code>&gt;</p><hr><h3 id="holdsmovementforteleport" tabindex="-1">holdsMovementForTeleport() <a class="header-anchor" href="#holdsmovementforteleport" aria-label="Permalink to “holdsMovementForTeleport()”">​</a></h3><blockquote><p><strong>holdsMovementForTeleport</strong>(<code>position</code>, <code>handledTeleport</code>): <code>boolean</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/1e6d90ea19aef765befd07dcc536f23d48c760b1/packages/prismarine/src/network/PlayerSession.ts#L2896" target="_blank" rel="noreferrer">prismarine/src/network/PlayerSession.ts:2896</a></p><p>Whether an input&#39;s position must be ignored because the client has not yet handled a teleport the server sent it.</p><p>Mojang&#39;s packet documentation, on <code>HandledTeleport</code>: &quot;The server should ignore any client predicted positions from the moment a MovePlayerPacket was sent until receipt of this action.&quot; That covers every teleport, the one that ends a dimension change included.</p><p>The client goes on sending inputs from where it was until it applies the <code>MovePlayer</code>, and the first input from the new place carries <code>HandledTeleport</code>. A retail client was captured doing exactly that, with one stale input arriving after the teleport about one time in three. Taking the stale position moves the player back on the server while the client stands at the target, and the server then sends chunks for the wrong place. A client that stops sending inputs while it waits for chunks never recovers from that.</p><p>The hold ends on a <code>HandledTeleport</code> input at the target, which tells two teleports sent in a row apart, or after TELEPORT_ACK_TIMEOUT_TICKS, so a client that never sets the flag is not frozen in place.</p><h4 id="parameters-11" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-11" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="position" tabindex="-1">position <a class="header-anchor" href="#position" aria-label="Permalink to “position”">​</a></h5><p><a href="./../../../../math/classes/Vector3.html"><code>Vector3</code></a></p><p>Where the input says the player is.</p><h5 id="handledteleport" tabindex="-1">handledTeleport <a class="header-anchor" href="#handledteleport" aria-label="Permalink to “handledTeleport”">​</a></h5><p><code>boolean</code></p><p>Whether the input carries <code>HandledTeleport</code>.</p><h4 id="returns-54" tabindex="-1">Returns <a class="header-anchor" href="#returns-54" aria-label="Permalink to “Returns”">​</a></h4><p><code>boolean</code></p><hr><h3 id="inputs" tabindex="-1">inputs() <a class="header-anchor" href="#inputs" aria-label="Permalink to “inputs()”">​</a></h3><blockquote><p><strong>inputs</strong>(): <code>EntityRuntime</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/1e6d90ea19aef765befd07dcc536f23d48c760b1/packages/prismarine/src/network/PlayerSession.ts#L3169" target="_blank" rel="noreferrer">prismarine/src/network/PlayerSession.ts:3169</a></p><p>The entity runtime of the player&#39;s world, whose player inputs write what the client reports: through its player systems while the player is in its store, and onto the store player&#39;s components while it is in none.</p><h4 id="returns-55" tabindex="-1">Returns <a class="header-anchor" href="#returns-55" aria-label="Permalink to “Returns”">​</a></h4><p><code>EntityRuntime</code></p><hr><h3 id="isconnected" tabindex="-1">isConnected() <a class="header-anchor" href="#isconnected" aria-label="Permalink to “isConnected()”">​</a></h3><blockquote><p><strong>isConnected</strong>(): <code>boolean</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/1e6d90ea19aef765befd07dcc536f23d48c760b1/packages/prismarine/src/network/PlayerSession.ts#L894" target="_blank" rel="noreferrer">prismarine/src/network/PlayerSession.ts:894</a></p><p>Whether the player has joined and not left.</p><h4 id="returns-56" tabindex="-1">Returns <a class="header-anchor" href="#returns-56" aria-label="Permalink to “Returns”">​</a></h4><p><code>boolean</code></p><hr><h3 id="isflying" tabindex="-1">isFlying() <a class="header-anchor" href="#isflying" aria-label="Permalink to “isFlying()”">​</a></h3><blockquote><p><strong>isFlying</strong>(): <code>boolean</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/1e6d90ea19aef765befd07dcc536f23d48c760b1/packages/prismarine/src/network/PlayerSession.ts#L3294" target="_blank" rel="noreferrer">prismarine/src/network/PlayerSession.ts:3294</a></p><p>Whether the player is flying.</p><h4 id="returns-57" tabindex="-1">Returns <a class="header-anchor" href="#returns-57" aria-label="Permalink to “Returns”">​</a></h4><p><code>boolean</code></p><hr><h3 id="isonground" tabindex="-1">isOnGround() <a class="header-anchor" href="#isonground" aria-label="Permalink to “isOnGround()”">​</a></h3><blockquote><p><strong>isOnGround</strong>(): <code>boolean</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/1e6d90ea19aef765befd07dcc536f23d48c760b1/packages/prismarine/src/network/PlayerSession.ts#L3279" target="_blank" rel="noreferrer">prismarine/src/network/PlayerSession.ts:3279</a></p><p>Whether the client last reported the player on the ground.</p><h4 id="returns-58" tabindex="-1">Returns <a class="header-anchor" href="#returns-58" aria-label="Permalink to “Returns”">​</a></h4><p><code>boolean</code></p><hr><h3 id="isop" tabindex="-1">isOp() <a class="header-anchor" href="#isop" aria-label="Permalink to “isOp()”">​</a></h3><blockquote><p><strong>isOp</strong>(): <code>boolean</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/1e6d90ea19aef765befd07dcc536f23d48c760b1/packages/prismarine/src/network/PlayerSession.ts#L3349" target="_blank" rel="noreferrer">prismarine/src/network/PlayerSession.ts:3349</a></p><p>Whether the player is an operator.</p><h4 id="returns-59" tabindex="-1">Returns <a class="header-anchor" href="#returns-59" aria-label="Permalink to “Returns”">​</a></h4><p><code>boolean</code></p><hr><h3 id="issneaking" tabindex="-1">isSneaking() <a class="header-anchor" href="#issneaking" aria-label="Permalink to “isSneaking()”">​</a></h3><blockquote><p><strong>isSneaking</strong>(): <code>boolean</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/1e6d90ea19aef765befd07dcc536f23d48c760b1/packages/prismarine/src/network/PlayerSession.ts#L3289" target="_blank" rel="noreferrer">prismarine/src/network/PlayerSession.ts:3289</a></p><p>Whether the client last reported the player sneaking.</p><h4 id="returns-60" tabindex="-1">Returns <a class="header-anchor" href="#returns-60" aria-label="Permalink to “Returns”">​</a></h4><p><code>boolean</code></p><hr><h3 id="issprinting" tabindex="-1">isSprinting() <a class="header-anchor" href="#issprinting" aria-label="Permalink to “isSprinting()”">​</a></h3><blockquote><p><strong>isSprinting</strong>(): <code>boolean</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/1e6d90ea19aef765befd07dcc536f23d48c760b1/packages/prismarine/src/network/PlayerSession.ts#L3284" target="_blank" rel="noreferrer">prismarine/src/network/PlayerSession.ts:3284</a></p><p>Whether the client last reported the player sprinting.</p><h4 id="returns-61" tabindex="-1">Returns <a class="header-anchor" href="#returns-61" aria-label="Permalink to “Returns”">​</a></h4><p><code>boolean</code></p><hr><h3 id="keyed" tabindex="-1">keyed() <a class="header-anchor" href="#keyed" aria-label="Permalink to “keyed()”">​</a></h3><blockquote><p><strong>keyed</strong>(): <code>KeyedPlayer</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/1e6d90ea19aef765befd07dcc536f23d48c760b1/packages/prismarine/src/network/PlayerSession.ts#L3216" target="_blank" rel="noreferrer">prismarine/src/network/PlayerSession.ts:3216</a></p><p>The key and the server the player&#39;s advancements and enchantment seed are kept by.</p><h4 id="returns-62" tabindex="-1">Returns <a class="header-anchor" href="#returns-62" aria-label="Permalink to “Returns”">​</a></h4><p><code>KeyedPlayer</code></p><hr><h3 id="kick" tabindex="-1">kick() <a class="header-anchor" href="#kick" aria-label="Permalink to “kick()”">​</a></h3><blockquote><p><strong>kick</strong>(<code>reason?</code>, <code>code?</code>): <code>Promise</code>&lt;<code>void</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/1e6d90ea19aef765befd07dcc536f23d48c760b1/packages/prismarine/src/network/PlayerSession.ts#L3112" target="_blank" rel="noreferrer">prismarine/src/network/PlayerSession.ts:3112</a></p><p>Disconnects this client with a reason it shows, and hangs up its connection.</p><h4 id="parameters-12" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-12" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="reason" tabindex="-1">reason? <a class="header-anchor" href="#reason" aria-label="Permalink to “reason?”">​</a></h5><p><code>string</code> = <code>&#39;unknown reason&#39;</code></p><p>Shown to the client.</p><h5 id="code" tabindex="-1">code? <a class="header-anchor" href="#code" aria-label="Permalink to “code?”">​</a></h5><p><a href="./../../../../minecraft/#disconnectreason"><code>DisconnectReason</code></a> = <code>DisconnectReason.KICKED</code></p><p>The code the client shows beside the reason. <code>Server.shutdown</code> passes <code>SHUTDOWN</code>.</p><h4 id="returns-63" tabindex="-1">Returns <a class="header-anchor" href="#returns-63" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>void</code>&gt;</p><h4 id="remarks-2" tabindex="-1">Remarks <a class="header-anchor" href="#remarks-2" aria-label="Permalink to “Remarks”">​</a></h4><p>Torn down through the connection rather than by calling <code>disable</code> directly, so the player and its session are released together and exactly once, and the RakNet session is hung up on rather than left for a client that never hangs up to hold its slot.</p><hr><h3 id="neednewchunks" tabindex="-1">needNewChunks() <a class="header-anchor" href="#neednewchunks" aria-label="Permalink to “needNewChunks()”">​</a></h3><blockquote><p><strong>needNewChunks</strong>(<code>forceResend?</code>, <code>dist?</code>): <code>Promise</code>&lt;<code>void</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/1e6d90ea19aef765befd07dcc536f23d48c760b1/packages/prismarine/src/network/PlayerSession.ts#L1264" target="_blank" rel="noreferrer">prismarine/src/network/PlayerSession.ts:1264</a></p><h4 id="parameters-13" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-13" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="forceresend" tabindex="-1">forceResend? <a class="header-anchor" href="#forceresend" aria-label="Permalink to “forceResend?”">​</a></h5><p><code>boolean</code> = <code>false</code></p><h5 id="dist" tabindex="-1">dist? <a class="header-anchor" href="#dist" aria-label="Permalink to “dist?”">​</a></h5><p><code>number</code></p><h4 id="returns-64" tabindex="-1">Returns <a class="header-anchor" href="#returns-64" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>void</code>&gt;</p><hr><h3 id="openblockcontainer" tabindex="-1">openBlockContainer() <a class="header-anchor" href="#openblockcontainer" aria-label="Permalink to “openBlockContainer()”">​</a></h3><blockquote><p><strong>openBlockContainer</strong>(<code>at</code>, <code>identifier</code>, <code>contents?</code>): <code>Promise</code>&lt;<a href="./../#openblockcontainer"><code>OpenBlockContainer</code></a> | <code>undefined</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/1e6d90ea19aef765befd07dcc536f23d48c760b1/packages/prismarine/src/network/PlayerSession.ts#L1597" target="_blank" rel="noreferrer">prismarine/src/network/PlayerSession.ts:1597</a></p><p>Opens the screen a block draws, with whatever the block is holding.</p><p>The one call the interaction path needs. Until this existed no block opened a container anywhere in this server: a chest, a furnace and a crafting table all did nothing when they were clicked, because <code>openMainInventory</code> was the only <code>ContainerOpen</code> ever sent.</p><p>The contents follow the open for the same reason they do there: a window whose contents never arrive is one the client has no reason to keep. Each packet uses the container name that screen assigns to its slots, so a furnace&#39;s fuel list arrives under its fuel name. A workstation stores nothing of its own, so no contents follow its open. A crafting table is followed by the player&#39;s own inventory under window 0 instead, which is what a Bedrock Dedicated Server 1.26.52 sent after a click on one. Repeated requests for the same open block return the current window without sending another open packet.</p><h4 id="parameters-14" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-14" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="at" tabindex="-1">at <a class="header-anchor" href="#at" aria-label="Permalink to “at”">​</a></h5><p><a href="./../../../../math/classes/Vector3.html"><code>Vector3</code></a></p><p>The block position, which is what <code>ContainerOpen</code> carries for a block.</p><h5 id="identifier" tabindex="-1">identifier <a class="header-anchor" href="#identifier" aria-label="Permalink to “identifier”">​</a></h5><p><code>string</code></p><p>The block standing there, which decides the screen.</p><h5 id="contents" tabindex="-1">contents? <a class="header-anchor" href="#contents" aria-label="Permalink to “contents?”">​</a></h5><p><code>ContainerEntry</code>[] = <code>[]</code></p><p>What the block holds, one entry per slot.</p><h4 id="returns-65" tabindex="-1">Returns <a class="header-anchor" href="#returns-65" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<a href="./../#openblockcontainer"><code>OpenBlockContainer</code></a> | <code>undefined</code>&gt;</p><p>The window it was opened under, or undefined when the block opens no screen.</p><hr><h3 id="openmaininventory" tabindex="-1">openMainInventory() <a class="header-anchor" href="#openmaininventory" aria-label="Permalink to “openMainInventory()”">​</a></h3><blockquote><p><strong>openMainInventory</strong>(): <code>Promise</code>&lt;<code>void</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/1e6d90ea19aef765befd07dcc536f23d48c760b1/packages/prismarine/src/network/PlayerSession.ts#L1567" target="_blank" rel="noreferrer">prismarine/src/network/PlayerSession.ts:1567</a></p><p>Opens the player&#39;s own inventory, as the client asked.</p><p>Under its own window id rather than under zero. Zero is the inventory the client always has open; asking it to <em>open</em> that one is asking for something it is already doing, and it answered by closing the window again straight away - which is as far as opening an inventory ever got, so no drag inside it was ever attempted.</p><p>The contents follow the open, because a window whose contents never arrive is one the client has no reason to keep.</p><h4 id="returns-66" tabindex="-1">Returns <a class="header-anchor" href="#returns-66" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>void</code>&gt;</p><h4 id="see" tabindex="-1">See <a class="header-anchor" href="#see" aria-label="Permalink to “See”">​</a></h4><p><a href="https://github.com/pmmp/PocketMine-MP/blob/stable/src/network/mcpe/InventoryManager.php" target="_blank" rel="noreferrer">https://github.com/pmmp/PocketMine-MP/blob/stable/src/network/mcpe/InventoryManager.php</a> (onClientOpenMainInventory)</p><hr><h3 id="opentradewindow" tabindex="-1">openTradeWindow() <a class="header-anchor" href="#opentradewindow" aria-label="Permalink to “openTradeWindow()”">​</a></h3><blockquote><p><strong>openTradeWindow</strong>(<code>trade</code>): <code>Promise</code>&lt;<a href="./../#openblockcontainer"><code>OpenBlockContainer</code></a> | <code>undefined</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/1e6d90ea19aef765befd07dcc536f23d48c760b1/packages/prismarine/src/network/PlayerSession.ts#L1705" target="_blank" rel="noreferrer">prismarine/src/network/PlayerSession.ts:1705</a></p><p>Opens a villager&#39;s trade screen and shows it the trader&#39;s offers.</p><p>The screen is a window like a block&#39;s: it has two payment slots the player&#39;s items go into and a result the trade comes out of, and closing it gives the payment back. It differs in being open on an actor, which the packet names, and in what follows the open: an <code>UpdateTradePacket</code> carrying the offers, which the client draws the screen from.</p><h4 id="parameters-15" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-15" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="trade" tabindex="-1">trade <a class="header-anchor" href="#trade" aria-label="Permalink to “trade”">​</a></h5><p><a href="./../#opentrade"><code>OpenTrade</code></a></p><p>The trader, where its offers come from and what happens when the player leaves.</p><h4 id="returns-67" tabindex="-1">Returns <a class="header-anchor" href="#returns-67" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<a href="./../#openblockcontainer"><code>OpenBlockContainer</code></a> | <code>undefined</code>&gt;</p><p>The window, or undefined when this session already has a trade open on that trader.</p><hr><h3 id="pendingcreditsarrival" tabindex="-1">pendingCreditsArrival() <a class="header-anchor" href="#pendingcreditsarrival" aria-label="Permalink to “pendingCreditsArrival()”">​</a></h3><blockquote><p><strong>pendingCreditsArrival</strong>(): <a href="./../#arrival"><code>Arrival</code></a> | <code>undefined</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/1e6d90ea19aef765befd07dcc536f23d48c760b1/packages/prismarine/src/network/PlayerSession.ts#L2597" target="_blank" rel="noreferrer">prismarine/src/network/PlayerSession.ts:2597</a></p><p>The arrival held while the credits roll on the client, or undefined when none are. While one is held, the client&#39;s <code>PlayerAuthInput</code> is dropped, as it is during a pending dimension change.</p><h4 id="returns-68" tabindex="-1">Returns <a class="header-anchor" href="#returns-68" aria-label="Permalink to “Returns”">​</a></h4><p><a href="./../#arrival"><code>Arrival</code></a> | <code>undefined</code></p><hr><h3 id="pendingdimensionchange" tabindex="-1">pendingDimensionChange() <a class="header-anchor" href="#pendingdimensionchange" aria-label="Permalink to “pendingDimensionChange()”">​</a></h3><blockquote><p><strong>pendingDimensionChange</strong>(): <a href="./../#pendingdimensionchange"><code>PendingDimensionChange</code></a> | <code>undefined</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/1e6d90ea19aef765befd07dcc536f23d48c760b1/packages/prismarine/src/network/PlayerSession.ts#L2526" target="_blank" rel="noreferrer">prismarine/src/network/PlayerSession.ts:2526</a></p><p>The world change the client has not yet finished loading into, or undefined when the player is settled. While one is pending, the client&#39;s positions are still the old world&#39;s and <code>PlayerAuthInputHandler</code> drops them.</p><h4 id="returns-69" tabindex="-1">Returns <a class="header-anchor" href="#returns-69" aria-label="Permalink to “Returns”">​</a></h4><p><a href="./../#pendingdimensionchange"><code>PendingDimensionChange</code></a> | <code>undefined</code></p><hr><h3 id="queuechunks" tabindex="-1">queueChunks() <a class="header-anchor" href="#queuechunks" aria-label="Permalink to “queueChunks()”">​</a></h3><blockquote><p><strong>queueChunks</strong>(<code>centerX</code>, <code>centerZ</code>, <code>coordinates</code>): <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/1e6d90ea19aef765befd07dcc536f23d48c760b1/packages/prismarine/src/network/PlayerSession.ts#L899" target="_blank" rel="noreferrer">prismarine/src/network/PlayerSession.ts:899</a></p><p>Queues the chunks around a position, nearest first, without sending anything yet.</p><h4 id="parameters-16" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-16" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="centerx" tabindex="-1">centerX <a class="header-anchor" href="#centerx" aria-label="Permalink to “centerX”">​</a></h5><p><code>number</code></p><h5 id="centerz" tabindex="-1">centerZ <a class="header-anchor" href="#centerz" aria-label="Permalink to “centerZ”">​</a></h5><p><code>number</code></p><h5 id="coordinates" tabindex="-1">coordinates <a class="header-anchor" href="#coordinates" aria-label="Permalink to “coordinates”">​</a></h5><p>[<code>number</code>, <code>number</code>][]</p><h4 id="returns-70" tabindex="-1">Returns <a class="header-anchor" href="#returns-70" aria-label="Permalink to “Returns”">​</a></h4><p><code>void</code></p><hr><h3 id="queuemoveactor" tabindex="-1">queueMoveActor() <a class="header-anchor" href="#queuemoveactor" aria-label="Permalink to “queueMoveActor()”">​</a></h3><blockquote><p><strong>queueMoveActor</strong>(<code>entity</code>, <code>teleport?</code>): <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/1e6d90ea19aef765befd07dcc536f23d48c760b1/packages/prismarine/src/network/PlayerSession.ts#L3075" target="_blank" rel="noreferrer">prismarine/src/network/PlayerSession.ts:3075</a></p><p>Adds an entity&#39;s movement to this tick&#39;s batch.</p><p>Sending each one on its own is what made mobs move in fits and starts, and for two reasons. Every packet became its own compressed batch and its own RakNet frame, so thirty mobs cost thirty compressions and thirty frames a tick, per player. Worse, <code>sendDataPacket</code> queues behind any chunk still compressing - so while a walking player streams terrain, every mob&#39;s movement waited behind it and then arrived in a burst. Mobs froze and jumped in exactly the rhythm the chunks were arriving in.</p><p>One batch a tick fixes both: one compression, one frame, and one place in the queue for the lot of them.</p><h4 id="parameters-17" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-17" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="entity-2" tabindex="-1">entity <a class="header-anchor" href="#entity-2" aria-label="Permalink to “entity”">​</a></h5><p><a href="./../#movedactor"><code>MovedActor</code></a></p><p>The entity that moved.</p><h5 id="teleport" tabindex="-1">teleport? <a class="header-anchor" href="#teleport" aria-label="Permalink to “teleport?”">​</a></h5><p><code>boolean</code> = <code>false</code></p><h4 id="returns-71" tabindex="-1">Returns <a class="header-anchor" href="#returns-71" aria-label="Permalink to “Returns”">​</a></h4><p><code>void</code></p><hr><h3 id="reconciletrackedentities" tabindex="-1">reconcileTrackedEntities() <a class="header-anchor" href="#reconciletrackedentities" aria-label="Permalink to “reconcileTrackedEntities()”">​</a></h3><blockquote><p><strong>reconcileTrackedEntities</strong>(<code>entities?</code>): <code>Promise</code>&lt;<code>void</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/1e6d90ea19aef765befd07dcc536f23d48c760b1/packages/prismarine/src/network/PlayerSession.ts#L986" target="_blank" rel="noreferrer">prismarine/src/network/PlayerSession.ts:986</a></p><p>Shows and hides entities so the client matches where the player now is.</p><p>Records an entity as tracked only <em>after</em> its spawn has gone out. Marking first would mean a spawn that failed left the entity flagged as delivered, and nothing would ever send it again - the same lesson <code>flushChunkBatch</code> records for chunks, where it left a permanent hole in the world.</p><h4 id="parameters-18" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-18" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="entities" tabindex="-1">entities? <a class="header-anchor" href="#entities" aria-label="Permalink to “entities?”">​</a></h5><p><code>Iterable</code>&lt;<code>ShownEntity</code>, <code>any</code>, <code>any</code>&gt;</p><p>Every entity in the world, and it must be every one - anything tracked and absent from it is taken to have left and is despawned. Defaults to asking the world. For a single arrival, use <a href="#considerentity">PlayerSession.considerEntity</a>.</p><h4 id="returns-72" tabindex="-1">Returns <a class="header-anchor" href="#returns-72" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>void</code>&gt;</p><hr><h3 id="recordinputtick" tabindex="-1">recordInputTick() <a class="header-anchor" href="#recordinputtick" aria-label="Permalink to “recordInputTick()”">​</a></h3><blockquote><p><strong>recordInputTick</strong>(<code>tick</code>): <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/1e6d90ea19aef765befd07dcc536f23d48c760b1/packages/prismarine/src/network/PlayerSession.ts#L2298" target="_blank" rel="noreferrer">prismarine/src/network/PlayerSession.ts:2298</a></p><p>Remember the tick of a <code>PlayerAuthInputPacket</code> just handled, so packets about this player can carry it as their <code>PlayerInputTick</code>.</p><p>Ticks only move forward; an input that arrives out of order does not wind the value back.</p><h4 id="parameters-19" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-19" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="tick" tabindex="-1">tick <a class="header-anchor" href="#tick" aria-label="Permalink to “tick”">​</a></h5><p><code>bigint</code></p><p>The packet&#39;s <code>Tick</code> field.</p><h4 id="returns-73" tabindex="-1">Returns <a class="header-anchor" href="#returns-73" aria-label="Permalink to “Returns”">​</a></h4><p><code>void</code></p><hr><h3 id="releasearrivalchunks" tabindex="-1">releaseArrivalChunks() <a class="header-anchor" href="#releasearrivalchunks" aria-label="Permalink to “releaseArrivalChunks()”">​</a></h3><blockquote><p><strong>releaseArrivalChunks</strong>(<code>loadingScreenId</code>): <code>Promise</code>&lt;<code>boolean</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/1e6d90ea19aef765befd07dcc536f23d48c760b1/packages/prismarine/src/network/PlayerSession.ts#L2616" target="_blank" rel="noreferrer">prismarine/src/network/PlayerSession.ts:2616</a></p><p>Lets the columns of a pending dimension change go out, once the client says it has opened that change&#39;s loading screen, and sends the ones already waiting.</p><p>Until then they are held. A client that decodes a column before it has switched dimension files it under the dimension it is leaving and drops it at the switch, then waits on its loading screen for a column the server believes it has: cinnabar did this on about one full e2e run in two. The client reports the screen open only after its switch has begun, so a column sent from then on lands in the new dimension. Sending the lost ones again is not a remedy: in sub chunk request mode a second <code>LevelChunk</code> resets the column the client holds, and a player standing on it falls through. ARRIVAL_HOLD_TICKS bounds the wait for a client that never reports the screen.</p><h4 id="parameters-20" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-20" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="loadingscreenid-1" tabindex="-1">loadingScreenId <a class="header-anchor" href="#loadingscreenid-1" aria-label="Permalink to “loadingScreenId”">​</a></h5><p><code>number</code></p><p>The id the client&#39;s <code>StartLoadingScreen</code> carried.</p><h4 id="returns-74" tabindex="-1">Returns <a class="header-anchor" href="#returns-74" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>boolean</code>&gt;</p><p>Whether this released the pending change&#39;s columns. Any other id changes nothing.</p><hr><h3 id="releasechangeheldoverdeath" tabindex="-1">releaseChangeHeldOverDeath() <a class="header-anchor" href="#releasechangeheldoverdeath" aria-label="Permalink to “releaseChangeHeldOverDeath()”">​</a></h3><blockquote><p><strong>releaseChangeHeldOverDeath</strong>(): <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/1e6d90ea19aef765befd07dcc536f23d48c760b1/packages/prismarine/src/network/PlayerSession.ts#L2506" target="_blank" rel="noreferrer">prismarine/src/network/PlayerSession.ts:2506</a></p><p>Files the change <a href="#changeworld">PlayerSession.changeWorld</a> held while the player was dead, for the next input step. Called by PlayerSession.respawn once the client is told its player is alive. A change still pending, the respawn&#39;s own included, files the held one when it closes instead.</p><h4 id="returns-75" tabindex="-1">Returns <a class="header-anchor" href="#returns-75" aria-label="Permalink to “Returns”">​</a></h4><p><code>void</code></p><hr><h3 id="released" tabindex="-1">released() <a class="header-anchor" href="#released" aria-label="Permalink to “released()”">​</a></h3><blockquote><p><strong>released</strong>(<code>sends</code>): <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/1e6d90ea19aef765befd07dcc536f23d48c760b1/packages/prismarine/src/network/PlayerSession.ts#L1195" target="_blank" rel="noreferrer">prismarine/src/network/PlayerSession.ts:1195</a></p><p>Lets sends that are already queued go without waiting for the transport, and logs a failure to frame them. For simulation code, which never reads the result of a send.</p><h4 id="parameters-21" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-21" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="sends" tabindex="-1">sends <a class="header-anchor" href="#sends" aria-label="Permalink to “sends”">​</a></h5><p><code>Promise</code>&lt;<code>void</code>&gt;</p><p>The sends, already started.</p><h4 id="returns-76" tabindex="-1">Returns <a class="header-anchor" href="#returns-76" aria-label="Permalink to “Returns”">​</a></h4><p><code>void</code></p><hr><h3 id="removefromplayerlist" tabindex="-1">removeFromPlayerList() <a class="header-anchor" href="#removefromplayerlist" aria-label="Permalink to “removeFromPlayerList()”">​</a></h3><blockquote><p><strong>removeFromPlayerList</strong>(): <code>Promise</code>&lt;<code>void</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/1e6d90ea19aef765befd07dcc536f23d48c760b1/packages/prismarine/src/network/PlayerSession.ts#L2929" target="_blank" rel="noreferrer">prismarine/src/network/PlayerSession.ts:2929</a></p><p>Removes a player from other players list</p><h4 id="returns-77" tabindex="-1">Returns <a class="header-anchor" href="#returns-77" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>void</code>&gt;</p><hr><h3 id="requestchunk" tabindex="-1">requestChunk() <a class="header-anchor" href="#requestchunk" aria-label="Permalink to “requestChunk()”">​</a></h3><blockquote><p><strong>requestChunk</strong>(<code>x</code>, <code>z</code>): <code>Promise</code>&lt;<code>void</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/1e6d90ea19aef765befd07dcc536f23d48c760b1/packages/prismarine/src/network/PlayerSession.ts#L1330" target="_blank" rel="noreferrer">prismarine/src/network/PlayerSession.ts:1330</a></p><h4 id="parameters-22" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-22" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="x-1" tabindex="-1">x <a class="header-anchor" href="#x-1" aria-label="Permalink to “x”">​</a></h5><p><code>number</code></p><h5 id="z-1" tabindex="-1">z <a class="header-anchor" href="#z-1" aria-label="Permalink to “z”">​</a></h5><p><code>number</code></p><h4 id="returns-78" tabindex="-1">Returns <a class="header-anchor" href="#returns-78" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>void</code>&gt;</p><hr><h3 id="requestrespawn" tabindex="-1">requestRespawn() <a class="header-anchor" href="#requestrespawn" aria-label="Permalink to “requestRespawn()”">​</a></h3><blockquote><p><strong>requestRespawn</strong>(): <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/1e6d90ea19aef765befd07dcc536f23d48c760b1/packages/prismarine/src/network/PlayerSession.ts#L3647" target="_blank" rel="noreferrer">prismarine/src/network/PlayerSession.ts:3647</a></p><p>Brings the player back after a death, at its respawn point and in one piece.</p><h4 id="returns-79" tabindex="-1">Returns <a class="header-anchor" href="#returns-79" aria-label="Permalink to “Returns”">​</a></h4><p><code>void</code></p><h4 id="remarks-3" tabindex="-1">Remarks <a class="header-anchor" href="#remarks-3" aria-label="Permalink to “Remarks”">​</a></h4><p>Called when the client asks, not when the player dies - the death screen is the client&#39;s, and it decides how long it stays up. The client reports <code>ClientReadyToSpawn</code> before it sends this, and has already put itself where the answer to that said: see <code>RespawnHandler</code>.</p><p>The respawn waits for the search&#39;s answer, so it is filed as a request and the input step that has the answer applies it (<a href="#requestrespawnpoint">requestRespawnPoint</a>).</p><hr><h3 id="requestrespawnpoint" tabindex="-1">requestRespawnPoint() <a class="header-anchor" href="#requestrespawnpoint" aria-label="Permalink to “requestRespawnPoint()”">​</a></h3><blockquote><p><strong>requestRespawnPoint</strong>(<code>apply</code>): <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/1e6d90ea19aef765befd07dcc536f23d48c760b1/packages/prismarine/src/network/PlayerSession.ts#L3560" target="_blank" rel="noreferrer">prismarine/src/network/PlayerSession.ts:3560</a></p><p>Where the player comes back after a death, given as a Bedrock Dedicated Server gives it.</p><p>Their own spawn point when they have one that still holds, in the world it was set in, which need not be the one they died in: a player who dies in the Nether with an Overworld bed comes back in the Overworld, as Java&#39;s <code>findRespawnPositionAndUseSpawnBlock</code> has it. Otherwise the Overworld spawn of the default level, which is Java&#39;s <code>server.overworld()</code>. A bed or a respawn anchor only holds a spawn while the block is still there with somewhere free to stand beside it, and a point <code>/spawnpoint</code> set is used whatever is standing there. The level&#39;s respawn search answers the question from plain data. A spawn that stopped holding is cleared here, so the player is told once rather than on every death.</p><p>The caller compares <code>world</code> with the player&#39;s own and changes world first when they differ: see <code>RespawnHandler</code>.</p><p>The search reads loaded chunks only, so the answer is not always there at once (<a href="#attemptrespawnpoint">attemptRespawnPoint</a>).</p><h4 id="parameters-23" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-23" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="apply" tabindex="-1">apply <a class="header-anchor" href="#apply" aria-label="Permalink to “apply”">​</a></h5><p>(<code>destination</code>) =&gt; <code>void</code></p><h4 id="returns-80" tabindex="-1">Returns <a class="header-anchor" href="#returns-80" aria-label="Permalink to “Returns”">​</a></h4><p><code>void</code></p><h4 id="see-1" tabindex="-1">See <a class="header-anchor" href="#see-1" aria-label="Permalink to “See”">​</a></h4><p>respawnPoint for the three positions the exchange needs.</p><hr><h3 id="send" tabindex="-1">send() <a class="header-anchor" href="#send" aria-label="Permalink to “send()”">​</a></h3><blockquote><p><strong>send</strong>(<code>packet</code>): <code>Promise</code>&lt;<code>void</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/1e6d90ea19aef765befd07dcc536f23d48c760b1/packages/prismarine/src/network/PlayerSession.ts#L1186" target="_blank" rel="noreferrer">prismarine/src/network/PlayerSession.ts:1186</a></p><p>Sends one packet to this client.</p><p>Returns the send rather than dropping it: without this, every <code>await session.send(...)</code> and every <code>Promise.all</code> over a broadcast resolved immediately and any framing error went nowhere.</p><h4 id="parameters-24" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-24" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="packet-2" tabindex="-1">packet <a class="header-anchor" href="#packet-2" aria-label="Permalink to “packet”">​</a></h5><p><a href="./../../../../protocol/classes/NetworkPacket.html"><code>NetworkPacket</code></a>&lt;<code>unknown</code>&gt;</p><p>The packet to send.</p><h4 id="returns-81" tabindex="-1">Returns <a class="header-anchor" href="#returns-81" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>void</code>&gt;</p><hr><h3 id="sendabilities" tabindex="-1">sendAbilities() <a class="header-anchor" href="#sendabilities" aria-label="Permalink to “sendAbilities()”">​</a></h3><blockquote><p><strong>sendAbilities</strong>(<code>player?</code>): <code>Promise</code>&lt;<code>void</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/1e6d90ea19aef765befd07dcc536f23d48c760b1/packages/prismarine/src/network/PlayerSession.ts#L1251" target="_blank" rel="noreferrer">prismarine/src/network/PlayerSession.ts:1251</a></p><p>Sends <code>UpdateAbilitiesPacket</code> describing <code>player</code> to this client (<code>abilitiesPacket</code>).</p><h4 id="parameters-25" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-25" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="player-1" tabindex="-1">player? <a class="header-anchor" href="#player-1" aria-label="Permalink to “player?”">​</a></h5><p><code>ShownPlayer</code></p><p>The player described. Defaults to this session&#39;s own player.</p><h4 id="returns-82" tabindex="-1">Returns <a class="header-anchor" href="#returns-82" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>void</code>&gt;</p><hr><h3 id="sendabilitychange" tabindex="-1">sendAbilityChange() <a class="header-anchor" href="#sendabilitychange" aria-label="Permalink to “sendAbilityChange()”">​</a></h3><blockquote><p><strong>sendAbilityChange</strong>(): <code>Promise</code>&lt;<code>void</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/1e6d90ea19aef765befd07dcc536f23d48c760b1/packages/prismarine/src/network/PlayerSession.ts#L1992" target="_blank" rel="noreferrer">prismarine/src/network/PlayerSession.ts:1992</a></p><p>The last sends of a game mode change, which read off the new game mode: the settings, the game type again, whether the player may fly, which is in its metadata, and its abilities.</p><h4 id="returns-83" tabindex="-1">Returns <a class="header-anchor" href="#returns-83" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>void</code>&gt;</p><hr><h3 id="sendarmorfor" tabindex="-1">sendArmorFor() <a class="header-anchor" href="#sendarmorfor" aria-label="Permalink to “sendArmorFor()”">​</a></h3><blockquote><p><strong>sendArmorFor</strong>(<code>wearer</code>): <code>Promise</code>&lt;<code>void</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/1e6d90ea19aef765befd07dcc536f23d48c760b1/packages/prismarine/src/network/PlayerSession.ts#L2986" target="_blank" rel="noreferrer">prismarine/src/network/PlayerSession.ts:2986</a></p><p>Tells this client what a human is wearing and holding in the off hand (<code>armorPackets</code>), read from the wearer&#39;s equipment, which for a player is its inventory.</p><h4 id="parameters-26" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-26" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="wearer" tabindex="-1">wearer <a class="header-anchor" href="#wearer" aria-label="Permalink to “wearer”">​</a></h5><p><code>ShownActor</code></p><p>Whose armor it is.</p><h4 id="returns-84" tabindex="-1">Returns <a class="header-anchor" href="#returns-84" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>void</code>&gt;</p><hr><h3 id="sendattributes" tabindex="-1">sendAttributes() <a class="header-anchor" href="#sendattributes" aria-label="Permalink to “sendAttributes()”">​</a></h3><blockquote><p><strong>sendAttributes</strong>(<code>attributes?</code>): <code>Promise</code>&lt;<code>void</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/1e6d90ea19aef765befd07dcc536f23d48c760b1/packages/prismarine/src/network/PlayerSession.ts#L2242" target="_blank" rel="noreferrer">prismarine/src/network/PlayerSession.ts:2242</a></p><p>Send the player&#39;s whole attribute set.</p><p>The client rebuilds the local player during the spawn sequence, so this has to be sent again once the player is in the world - anything sent before that is thrown away, which is why the hunger bar sat empty however correct the values were here.</p><h4 id="parameters-27" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-27" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="attributes-1" tabindex="-1">attributes? <a class="header-anchor" href="#attributes-1" aria-label="Permalink to “attributes?”">​</a></h5><p><code>Attributes</code> = <code>...</code></p><p>The attributes to send, the player&#39;s own by default.</p><h4 id="returns-85" tabindex="-1">Returns <a class="header-anchor" href="#returns-85" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>void</code>&gt;</p><hr><h3 id="sendattributesfor" tabindex="-1">sendAttributesFor() <a class="header-anchor" href="#sendattributesfor" aria-label="Permalink to “sendAttributesFor()”">​</a></h3><blockquote><p><strong>sendAttributesFor</strong>(<code>entity</code>, <code>attributes</code>): <code>Promise</code>&lt;<code>void</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/1e6d90ea19aef765befd07dcc536f23d48c760b1/packages/prismarine/src/network/PlayerSession.ts#L2279" target="_blank" rel="noreferrer">prismarine/src/network/PlayerSession.ts:2279</a></p><p>Tell this client about <em>another</em> entity&#39;s changed attributes.</p><p>The gap that made mob combat invisible. Everything above sends the local player&#39;s own attributes, with their runtime id baked in, so a mob losing health changed a number on the server that no client was ever told about - the health bar over a hurt zombie never moved, and it died in one apparent hit from full. Attributes only reached a client once, inside the <code>AddActorPacket</code> that spawned the entity.</p><h4 id="parameters-28" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-28" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="entity-3" tabindex="-1">entity <a class="header-anchor" href="#entity-3" aria-label="Permalink to “entity”">​</a></h5><p><code>Pick</code>&lt;<code>ShownActor</code>, <code>&quot;getRuntimeId&quot;</code>&gt;</p><p>Whose attributes these are.</p><h5 id="attributes-2" tabindex="-1">attributes <a class="header-anchor" href="#attributes-2" aria-label="Permalink to “attributes”">​</a></h5><p><code>Attribute</code>[]</p><p>The ones that changed; nothing is sent for an empty list.</p><h4 id="returns-86" tabindex="-1">Returns <a class="header-anchor" href="#returns-86" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>void</code>&gt;</p><hr><h3 id="sendavailablecommands" tabindex="-1">sendAvailableCommands() <a class="header-anchor" href="#sendavailablecommands" aria-label="Permalink to “sendAvailableCommands()”">​</a></h3><blockquote><p><strong>sendAvailableCommands</strong>(): <code>Promise</code>&lt;<code>void</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/1e6d90ea19aef765befd07dcc536f23d48c760b1/packages/prismarine/src/network/PlayerSession.ts#L2037" target="_blank" rel="noreferrer">prismarine/src/network/PlayerSession.ts:2037</a></p><p>Tells the client which commands this player may run and what each one takes.</p><p>One <code>CommandData</code> per command, each branch of its tree an overload, with overloads that come out the same folded into one. Only commands the player&#39;s permissions allow are sent, so the list is built per recipient and sent again when those permissions change.</p><p>The list is the command manager&#39;s one registry, already flattened into Bedrock&#39;s overload shape by <code>@jsprismarine/commands</code>, which carries chained subcommands and therefore the chained <code>/execute</code> tree.</p><h4 id="returns-87" tabindex="-1">Returns <a class="header-anchor" href="#returns-87" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>void</code>&gt;</p><hr><h3 id="sendcontainerdata" tabindex="-1">sendContainerData() <a class="header-anchor" href="#sendcontainerdata" aria-label="Permalink to “sendContainerData()”">​</a></h3><blockquote><p><strong>sendContainerData</strong>(<code>at</code>, <code>properties</code>): <code>Promise</code>&lt;<code>void</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/1e6d90ea19aef765befd07dcc536f23d48c760b1/packages/prismarine/src/network/PlayerSession.ts#L1787" target="_blank" rel="noreferrer">prismarine/src/network/PlayerSession.ts:1787</a></p><p>Sets properties on the open block container&#39;s screen, which is how a progress bar moves.</p><p>A property whose value has not changed since the last send is skipped; see PlayerSession.containerData. Nothing is sent when the screen was opened from a different block, so a station ticking across the world cannot write over the screen the player is actually looking at.</p><h4 id="parameters-29" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-29" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="at-1" tabindex="-1">at <a class="header-anchor" href="#at-1" aria-label="Permalink to “at”">​</a></h5><p><a href="./../../../../math/classes/Vector3.html"><code>Vector3</code></a></p><p>The block the properties belong to.</p><h5 id="properties-1" tabindex="-1">properties <a class="header-anchor" href="#properties-1" aria-label="Permalink to “properties”">​</a></h5><p><code>ReadonlyMap</code>&lt;<code>number</code>, <code>number</code>&gt;</p><p>The property values by id, as the station reports them.</p><h4 id="returns-88" tabindex="-1">Returns <a class="header-anchor" href="#returns-88" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>void</code>&gt;</p><hr><h3 id="sendcontainerslot" tabindex="-1">sendContainerSlot() <a class="header-anchor" href="#sendcontainerslot" aria-label="Permalink to “sendContainerSlot()”">​</a></h3><blockquote><p><strong>sendContainerSlot</strong>(<code>windowId</code>, <code>containerId</code>, <code>slot</code>, <code>item</code>): <code>Promise</code>&lt;<code>void</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/1e6d90ea19aef765befd07dcc536f23d48c760b1/packages/prismarine/src/network/PlayerSession.ts#L1506" target="_blank" rel="noreferrer">prismarine/src/network/PlayerSession.ts:1506</a></p><p>Tells this client that one slot of a container it has open now holds something else.</p><p>An <code>ItemStackResponse</code> only ever reaches the client that sent the request, so this is the only way to tell the other players standing at the same chest that a stack has gone.</p><h4 id="parameters-30" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-30" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="windowid-1" tabindex="-1">windowId <a class="header-anchor" href="#windowid-1" aria-label="Permalink to “windowId”">​</a></h5><p><code>number</code></p><p>The <code>Container Id</code> this client opened the block under, which is its own.</p><h5 id="containerid" tabindex="-1">containerId <a class="header-anchor" href="#containerid" aria-label="Permalink to “containerId”">​</a></h5><p><code>number</code></p><p>The <code>Container Name</code> the client numbers the slot by.</p><h5 id="slot" tabindex="-1">slot <a class="header-anchor" href="#slot" aria-label="Permalink to “slot”">​</a></h5><p><code>number</code></p><p>The slot within that container.</p><h5 id="item" tabindex="-1">item <a class="header-anchor" href="#item" aria-label="Permalink to “item”">​</a></h5><p><code>Item</code> | <code>null</code></p><p>What is in it now, or <code>null</code> to empty it.</p><h4 id="returns-89" tabindex="-1">Returns <a class="header-anchor" href="#returns-89" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>void</code>&gt;</p><hr><h3 id="sendcraftingdata" tabindex="-1">sendCraftingData() <a class="header-anchor" href="#sendcraftingdata" aria-label="Permalink to “sendCraftingData()”">​</a></h3><blockquote><p><strong>sendCraftingData</strong>(): <code>Promise</code>&lt;<code>void</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/1e6d90ea19aef765befd07dcc536f23d48c760b1/packages/prismarine/src/network/PlayerSession.ts#L1860" target="_blank" rel="noreferrer">prismarine/src/network/PlayerSession.ts:1860</a></p><p>Tells the client which recipes exist.</p><p>Until it has these the client proposes nothing and never sends a <code>CRAFTING_RECIPE</code>, so everything below this - the matcher, the stations, the grid - is invisible without it.</p><p>The recipes come from the content build&#39;s recipe book, and a recipe&#39;s net id is its position in that book, which is what an <code>ItemStackRequest</code> names it by. A build that produced no payload sends nothing, so the client proposes nothing it cannot craft.</p><p>How many go out is <code>crafting-recipe-limit</code> in the config: <code>0</code> sends nothing, <code>-1</code> sends everything, and it starts at one. See there for why.</p><h4 id="returns-90" tabindex="-1">Returns <a class="header-anchor" href="#returns-90" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>void</code>&gt;</p><hr><h3 id="sendcreativecontents" tabindex="-1">sendCreativeContents() <a class="header-anchor" href="#sendcreativecontents" aria-label="Permalink to “sendCreativeContents()”">​</a></h3><blockquote><p><strong>sendCreativeContents</strong>(<code>empty?</code>): <code>Promise</code>&lt;<code>void</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/1e6d90ea19aef765befd07dcc536f23d48c760b1/packages/prismarine/src/network/PlayerSession.ts#L1885" target="_blank" rel="noreferrer">prismarine/src/network/PlayerSession.ts:1885</a></p><h4 id="parameters-31" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-31" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="empty" tabindex="-1">empty? <a class="header-anchor" href="#empty" aria-label="Permalink to “empty?”">​</a></h5><p><code>boolean</code> = <code>false</code></p><h4 id="returns-91" tabindex="-1">Returns <a class="header-anchor" href="#returns-91" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>void</code>&gt;</p><hr><h3 id="senddeathscreen" tabindex="-1">sendDeathScreen() <a class="header-anchor" href="#senddeathscreen" aria-label="Permalink to “sendDeathScreen()”">​</a></h3><blockquote><p><strong>sendDeathScreen</strong>(<code>announced</code>, <code>cause</code>): <code>Promise</code>&lt;<code>void</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/1e6d90ea19aef765befd07dcc536f23d48c760b1/packages/prismarine/src/network/PlayerSession.ts#L2775" target="_blank" rel="noreferrer">prismarine/src/network/PlayerSession.ts:2775</a></p><p>The death screen&#39;s half of a death, once the respawn search has answered: where the player will come back, which the client waits for before it offers the respawn button, and then the screen&#39;s own copy of the cause, as PocketMine&#39;s <code>DeathPacketHandler</code> sends it after the <code>Respawn</code>.</p><h4 id="parameters-32" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-32" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="announced" tabindex="-1">announced <a class="header-anchor" href="#announced" aria-label="Permalink to “announced”">​</a></h5><p><a href="./../../../../math/classes/Vector3.html"><code>Vector3</code></a></p><p>Where the player will reappear.</p><h5 id="cause" tabindex="-1">cause <a class="header-anchor" href="#cause" aria-label="Permalink to “cause”">​</a></h5><p><code>DeathMessage</code></p><p>The death message, as the chat line has it. <code>DeathInfo</code> takes the key without the <code>%</code> the chat packet wants.</p><h4 id="returns-92" tabindex="-1">Returns <a class="header-anchor" href="#returns-92" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>void</code>&gt;</p><hr><h3 id="sendgamemode" tabindex="-1">sendGamemode() <a class="header-anchor" href="#sendgamemode" aria-label="Permalink to “sendGamemode()”">​</a></h3><blockquote><p><strong>sendGamemode</strong>(<code>gamemode?</code>): <code>Promise</code>&lt;<code>void</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/1e6d90ea19aef765befd07dcc536f23d48c760b1/packages/prismarine/src/network/PlayerSession.ts#L1946" target="_blank" rel="noreferrer">prismarine/src/network/PlayerSession.ts:1946</a></p><p>Send gamemode to a client.</p><h4 id="parameters-33" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-33" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="gamemode-1" tabindex="-1">gamemode? <a class="header-anchor" href="#gamemode-1" aria-label="Permalink to “gamemode?”">​</a></h5><p><a href="./../../../../minecraft/#gametype"><code>Gametype</code></a></p><p>the numeric gamemode ID.</p><h4 id="returns-93" tabindex="-1">Returns <a class="header-anchor" href="#returns-93" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>void</code>&gt;</p><hr><h3 id="sendgamerules" tabindex="-1">sendGameRules() <a class="header-anchor" href="#sendgamerules" aria-label="Permalink to “sendGameRules()”">​</a></h3><blockquote><p><strong>sendGameRules</strong>(<code>rules</code>): <code>Promise</code>&lt;<code>void</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/1e6d90ea19aef765befd07dcc536f23d48c760b1/packages/prismarine/src/network/PlayerSession.ts#L2010" target="_blank" rel="noreferrer">prismarine/src/network/PlayerSession.ts:2010</a></p><p>Tells this client that game rules changed.</p><h4 id="parameters-34" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-34" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="rules" tabindex="-1">rules <a class="header-anchor" href="#rules" aria-label="Permalink to “rules”">​</a></h5><p><code>GameRule</code>[]</p><p>The rules that changed, spelled as the client spells them.</p><h4 id="returns-94" tabindex="-1">Returns <a class="header-anchor" href="#returns-94" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>void</code>&gt;</p><hr><h3 id="sendgametypechange" tabindex="-1">sendGameTypeChange() <a class="header-anchor" href="#sendgametypechange" aria-label="Permalink to “sendGameTypeChange()”">​</a></h3><blockquote><p><strong>sendGameTypeChange</strong>(): <code>Promise</code>&lt;<code>void</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/1e6d90ea19aef765befd07dcc536f23d48c760b1/packages/prismarine/src/network/PlayerSession.ts#L1975" target="_blank" rel="noreferrer">prismarine/src/network/PlayerSession.ts:1975</a></p><p>The first sends of a game mode change: this client&#39;s own game type, and the game type every client in the world caches for this player. Replication sends the metadata a game mode decides, not the game type, so these are the sends. <a href="#sendabilitychange">PlayerSession.sendAbilityChange</a> follows them.</p><h4 id="returns-95" tabindex="-1">Returns <a class="header-anchor" href="#returns-95" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>void</code>&gt;</p><hr><h3 id="sendgametypefor" tabindex="-1">sendGameTypeFor() <a class="header-anchor" href="#sendgametypefor" aria-label="Permalink to “sendGameTypeFor()”">​</a></h3><blockquote><p><strong>sendGameTypeFor</strong>(<code>target</code>): <code>Promise</code>&lt;<code>void</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/1e6d90ea19aef765befd07dcc536f23d48c760b1/packages/prismarine/src/network/PlayerSession.ts#L1961" target="_blank" rel="noreferrer">prismarine/src/network/PlayerSession.ts:1961</a></p><p>Tells this client which game type a player now has.</p><p><code>UpdatePlayerGameTypePacket</code> is what the docs have the server send to every client after it accepts a game type change, because each client caches the game type and permission flags of every player it knows about. The Tick is this client&#39;s last input tick when the player is its own, so the client can reconcile the movement it predicted while the packet was in flight, and zero for anyone else, as the docs allow.</p><h4 id="parameters-35" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-35" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="target" tabindex="-1">target <a class="header-anchor" href="#target" aria-label="Permalink to “target”">​</a></h5><p><code>ShownPlayer</code></p><p>The player whose game type changed.</p><h4 id="returns-96" tabindex="-1">Returns <a class="header-anchor" href="#returns-96" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>void</code>&gt;</p><hr><h3 id="sendhanditem" tabindex="-1">sendHandItem() <a class="header-anchor" href="#sendhanditem" aria-label="Permalink to “sendHandItem()”">​</a></h3><blockquote><p><strong>sendHandItem</strong>(<code>item</code>): <code>Promise</code>&lt;<code>void</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/1e6d90ea19aef765befd07dcc536f23d48c760b1/packages/prismarine/src/network/PlayerSession.ts#L1920" target="_blank" rel="noreferrer">prismarine/src/network/PlayerSession.ts:1920</a></p><p>Sets the item in the player hand.</p><h4 id="parameters-36" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-36" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="item-1" tabindex="-1">item <a class="header-anchor" href="#item-1" aria-label="Permalink to “item”">​</a></h5><p><code>Item</code></p><p>The entity.</p><h4 id="returns-97" tabindex="-1">Returns <a class="header-anchor" href="#returns-97" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>void</code>&gt;</p><hr><h3 id="sendinitialspawnchunks" tabindex="-1">sendInitialSpawnChunks() <a class="header-anchor" href="#sendinitialspawnchunks" aria-label="Permalink to “sendInitialSpawnChunks()”">​</a></h3><blockquote><p><strong>sendInitialSpawnChunks</strong>(): <code>Promise</code>&lt;<code>void</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/1e6d90ea19aef765befd07dcc536f23d48c760b1/packages/prismarine/src/network/PlayerSession.ts#L2114" target="_blank" rel="noreferrer">prismarine/src/network/PlayerSession.ts:2114</a></p><p>Opens the window the client accepts chunks in and queues the chunks around the player, with an initial view radius of DEFAULT_VIEW_DISTANCE_CHUNKS, as a join and a world change start.</p><h4 id="returns-98" tabindex="-1">Returns <a class="header-anchor" href="#returns-98" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>void</code>&gt;</p><hr><h3 id="sendinventory" tabindex="-1">sendInventory() <a class="header-anchor" href="#sendinventory" aria-label="Permalink to “sendInventory()”">​</a></h3><blockquote><p><strong>sendInventory</strong>(<code>windowId?</code>): <code>Promise</code>&lt;<code>void</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/1e6d90ea19aef765befd07dcc536f23d48c760b1/packages/prismarine/src/network/PlayerSession.ts#L1457" target="_blank" rel="noreferrer">prismarine/src/network/PlayerSession.ts:1457</a></p><p>Tells the client what the player is carrying.</p><p>The send was commented out, so the client was never told: it had no model of the player&#39;s own slots, and the server authoritative inventory system will not move a stack into a container it does not know. Every drag was refused on the client&#39;s side, before an <code>ItemStackRequest</code> was ever sent.</p><h4 id="parameters-37" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-37" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="windowid-2" tabindex="-1">windowId? <a class="header-anchor" href="#windowid-2" aria-label="Permalink to “windowId?”">​</a></h5><p><code>number</code> = <code>WindowIds.INVENTORY</code></p><h4 id="returns-99" tabindex="-1">Returns <a class="header-anchor" href="#returns-99" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>void</code>&gt;</p><hr><h3 id="sendmessage" tabindex="-1">sendMessage() <a class="header-anchor" href="#sendmessage" aria-label="Permalink to “sendMessage()”">​</a></h3><blockquote><p><strong>sendMessage</strong>(<code>delivery</code>): <code>Promise</code>&lt;<code>void</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/1e6d90ea19aef765befd07dcc536f23d48c760b1/packages/prismarine/src/network/PlayerSession.ts#L2796" target="_blank" rel="noreferrer">prismarine/src/network/PlayerSession.ts:2796</a></p><p>Send a chat message to the client.</p><p>A bare string is a raw line, which is how a command answers the player that ran it.</p><h4 id="parameters-38" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-38" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="delivery" tabindex="-1">delivery <a class="header-anchor" href="#delivery" aria-label="Permalink to “delivery”">​</a></h5><p><code>string</code> | { <code>message</code>: <code>string</code>; <code>needsTranslation?</code>: <code>boolean</code>; <code>parameters?</code>: <code>string</code>[]; <code>platformChatId?</code>: <code>string</code>; <code>sourceName?</code>: <code>string</code>; <code>type?</code>: <a href="./../../../../protocol/#textpackettype"><code>TextPacketType</code></a>; <code>xuid?</code>: <code>string</code>; }</p><p>The message, or the options for it.</p><p><code>string</code></p><hr><h6 id="type-literal" tabindex="-1">Type Literal <a class="header-anchor" href="#type-literal" aria-label="Permalink to “Type Literal”">​</a></h6><p>{ <code>message</code>: <code>string</code>; <code>needsTranslation?</code>: <code>boolean</code>; <code>parameters?</code>: <code>string</code>[]; <code>platformChatId?</code>: <code>string</code>; <code>sourceName?</code>: <code>string</code>; <code>type?</code>: <a href="./../../../../protocol/#textpackettype"><code>TextPacketType</code></a>; <code>xuid?</code>: <code>string</code>; }</p><p>The message, or the options for it.</p><h6 id="message" tabindex="-1">message <a class="header-anchor" href="#message" aria-label="Permalink to “message”">​</a></h6><p><code>string</code></p><p>The message to send.</p><h6 id="needstranslation" tabindex="-1">needsTranslation? <a class="header-anchor" href="#needstranslation" aria-label="Permalink to “needsTranslation?”">​</a></h6><p><code>boolean</code></p><p>Whether the message needs translation.</p><h6 id="parameters-39" tabindex="-1">parameters? <a class="header-anchor" href="#parameters-39" aria-label="Permalink to “parameters?”">​</a></h6><p><code>string</code>[]</p><p>The parameters for the message.</p><h6 id="platformchatid" tabindex="-1">platformChatId? <a class="header-anchor" href="#platformchatid" aria-label="Permalink to “platformChatId?”">​</a></h6><p><code>string</code></p><p>The platform chat ID.</p><h6 id="sourcename" tabindex="-1">sourceName? <a class="header-anchor" href="#sourcename" aria-label="Permalink to “sourceName?”">​</a></h6><p><code>string</code></p><p>The source of the message.</p><h6 id="type" tabindex="-1">type? <a class="header-anchor" href="#type" aria-label="Permalink to “type?”">​</a></h6><p><a href="./../../../../protocol/#textpackettype"><code>TextPacketType</code></a></p><p>The type of the message.</p><h6 id="xuid" tabindex="-1">xuid? <a class="header-anchor" href="#xuid" aria-label="Permalink to “xuid?”">​</a></h6><p><code>string</code></p><p>The XUID of the player.</p><h4 id="returns-100" tabindex="-1">Returns <a class="header-anchor" href="#returns-100" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>void</code>&gt;</p><p>A promise that resolves when the message is sent.</p><hr><h3 id="sendmetadata" tabindex="-1">sendMetadata() <a class="header-anchor" href="#sendmetadata" aria-label="Permalink to “sendMetadata()”">​</a></h3><blockquote><p><strong>sendMetadata</strong>(<code>metadata?</code>): <code>Promise</code>&lt;<code>void</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/1e6d90ea19aef765befd07dcc536f23d48c760b1/packages/prismarine/src/network/PlayerSession.ts#L2690" target="_blank" rel="noreferrer">prismarine/src/network/PlayerSession.ts:2690</a></p><h4 id="parameters-40" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-40" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="metadata" tabindex="-1">metadata? <a class="header-anchor" href="#metadata" aria-label="Permalink to “metadata?”">​</a></h5><p><code>Metadata</code></p><h4 id="returns-101" tabindex="-1">Returns <a class="header-anchor" href="#returns-101" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>void</code>&gt;</p><hr><h3 id="sendmetadatafor" tabindex="-1">sendMetadataFor() <a class="header-anchor" href="#sendmetadatafor" aria-label="Permalink to “sendMetadataFor()”">​</a></h3><blockquote><p><strong>sendMetadataFor</strong>(<code>entity</code>, <code>metadata?</code>): <code>Promise</code>&lt;<code>void</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/1e6d90ea19aef765befd07dcc536f23d48c760b1/packages/prismarine/src/network/PlayerSession.ts#L2704" target="_blank" rel="noreferrer">prismarine/src/network/PlayerSession.ts:2704</a></p><p>Tell this client what <em>another</em> entity now looks like.</p><p>The same gap <code>sendAttributesFor</code> fills, for the other half of an entity&#39;s state: everything above had the local player&#39;s runtime id baked in, so metadata reached a client exactly once, inside the packet that spawned the entity. A creeper could light its fuse, a mob could catch fire, and nobody would ever see either.</p><h4 id="parameters-41" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-41" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="entity-4" tabindex="-1">entity <a class="header-anchor" href="#entity-4" aria-label="Permalink to “entity”">​</a></h5><p><code>Pick</code>&lt;<code>ShownActor</code>, <code>&quot;getRuntimeId&quot;</code> | <code>&quot;metadata&quot;</code> | <code>&quot;getSyncedProperties&quot;</code>&gt;</p><p>Whose metadata this is.</p><h5 id="metadata-1" tabindex="-1">metadata? <a class="header-anchor" href="#metadata-1" aria-label="Permalink to “metadata?”">​</a></h5><p><code>Metadata</code></p><p>What to send; the entity&#39;s own by default.</p><h4 id="returns-102" tabindex="-1">Returns <a class="header-anchor" href="#returns-102" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>void</code>&gt;</p><hr><h3 id="sendmotion" tabindex="-1">sendMotion() <a class="header-anchor" href="#sendmotion" aria-label="Permalink to “sendMotion()”">​</a></h3><blockquote><p><strong>sendMotion</strong>(<code>motion</code>): <code>Promise</code>&lt;<code>void</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/1e6d90ea19aef765befd07dcc536f23d48c760b1/packages/prismarine/src/network/PlayerSession.ts#L2682" target="_blank" rel="noreferrer">prismarine/src/network/PlayerSession.ts:2682</a></p><p>Hand the client a velocity and let it move the player itself.</p><p>The only way to shove a player. Their position is theirs - the server stores what it is told - so setting it from here is overruled by the next movement packet and read as rubber-banding. A velocity is a request the client is happy to honor.</p><p>The <code>Tick</code> is the client&#39;s last input tick, as the docs ask for a packet about the player: the client rewinds to that tick, applies the velocity and replays what it predicted since. See <a href="#recordinputtick">PlayerSession.recordInputTick</a>.</p><h4 id="parameters-42" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-42" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="motion" tabindex="-1">motion <a class="header-anchor" href="#motion" aria-label="Permalink to “motion”">​</a></h5><p><a href="./../../../../math/classes/Vector3.html"><code>Vector3</code></a></p><p>Blocks per tick, in each axis.</p><h4 id="returns-103" tabindex="-1">Returns <a class="header-anchor" href="#returns-103" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>void</code>&gt;</p><hr><h3 id="sendmove" tabindex="-1">sendMove() <a class="header-anchor" href="#sendmove" aria-label="Permalink to “sendMove()”">​</a></h3><blockquote><p><strong>sendMove</strong>(<code>player</code>, <code>mode?</code>): <code>Promise</code>&lt;<code>void</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/1e6d90ea19aef765befd07dcc536f23d48c760b1/packages/prismarine/src/network/PlayerSession.ts#L2850" target="_blank" rel="noreferrer">prismarine/src/network/PlayerSession.ts:2850</a></p><p>Sends one player&#39;s movement to this client.</p><p>Named for what it does. It was <code>broadcastMove</code>, which reads as a fan-out and is not one - the fan-out is <code>World.broadcastMove</code>, and having both made it easy to write the wrong one.</p><p>For this client&#39;s own player the packet is a server-initiated move: a teleport, a respawn, or a reset after a canceled move event. Its <code>Tick</code> is the client&#39;s last input tick, as the docs ask, so the client rewinds to it and replays its predictions from there. For any other player the packet is what this client sees of them, and the tick is zero because it relates to none of this client&#39;s inputs.</p><h4 id="parameters-43" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-43" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="player-2" tabindex="-1">player <a class="header-anchor" href="#player-2" aria-label="Permalink to “player”">​</a></h5><p><code>ShownActor</code></p><p>The player that moved.</p><h5 id="mode" tabindex="-1">mode? <a class="header-anchor" href="#mode" aria-label="Permalink to “mode?”">​</a></h5><p><a href="./../../../../protocol/#positionmode"><code>PositionMode</code></a> = <code>PositionMode.Normal</code></p><p>What produced the movement.</p><h4 id="returns-104" tabindex="-1">Returns <a class="header-anchor" href="#returns-104" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>void</code>&gt;</p><hr><h3 id="sendmoveactor" tabindex="-1">sendMoveActor() <a class="header-anchor" href="#sendmoveactor" aria-label="Permalink to “sendMoveActor()”">​</a></h3><blockquote><p><strong>sendMoveActor</strong>(<code>entity</code>): <code>Promise</code>&lt;<code>void</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/1e6d90ea19aef765befd07dcc536f23d48c760b1/packages/prismarine/src/network/PlayerSession.ts#L3057" target="_blank" rel="noreferrer">prismarine/src/network/PlayerSession.ts:3057</a></p><p>Tells this connection an entity has moved, on its own.</p><p>For a move that happens outside the world tick - a teleport, a command. Movement produced by the tick goes through <a href="#queuemoveactor">queueMoveActor</a> instead.</p><h4 id="parameters-44" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-44" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="entity-5" tabindex="-1">entity <a class="header-anchor" href="#entity-5" aria-label="Permalink to “entity”">​</a></h5><p><a href="./../#movedactor"><code>MovedActor</code></a></p><p>The entity that moved.</p><h4 id="returns-105" tabindex="-1">Returns <a class="header-anchor" href="#returns-105" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>void</code>&gt;</p><hr><h3 id="sendnetworkchunkpublisher" tabindex="-1">sendNetworkChunkPublisher() <a class="header-anchor" href="#sendnetworkchunkpublisher" aria-label="Permalink to “sendNetworkChunkPublisher()”">​</a></h3><blockquote><p><strong>sendNetworkChunkPublisher</strong>(<code>distance</code>, <code>savedChunks</code>): <code>Promise</code>&lt;<code>void</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/1e6d90ea19aef765befd07dcc536f23d48c760b1/packages/prismarine/src/network/PlayerSession.ts#L2016" target="_blank" rel="noreferrer">prismarine/src/network/PlayerSession.ts:2016</a></p><h4 id="parameters-45" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-45" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="distance" tabindex="-1">distance <a class="header-anchor" href="#distance" aria-label="Permalink to “distance”">​</a></h5><p><code>number</code></p><h5 id="savedchunks" tabindex="-1">savedChunks <a class="header-anchor" href="#savedchunks" aria-label="Permalink to “savedChunks”">​</a></h5><p><a href="./../../../../protocol/#chunkcoord"><code>ChunkCoord</code></a>[]</p><h4 id="returns-106" tabindex="-1">Returns <a class="header-anchor" href="#returns-106" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>void</code>&gt;</p><hr><h3 id="sendownslot" tabindex="-1">sendOwnSlot() <a class="header-anchor" href="#sendownslot" aria-label="Permalink to “sendOwnSlot()”">​</a></h3><blockquote><p><strong>sendOwnSlot</strong>(<code>container</code>, <code>slot</code>): <code>Promise</code>&lt;<code>void</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/1e6d90ea19aef765befd07dcc536f23d48c760b1/packages/prismarine/src/network/PlayerSession.ts#L1533" target="_blank" rel="noreferrer">prismarine/src/network/PlayerSession.ts:1533</a></p><p>Tells this client what one of its player&#39;s own slots holds now, under the stack network id the client is to name it by. Replication sends it for a <code>slot-shown</code> occurrence: a slot whose write was undone holds a stack with a new id.</p><h4 id="parameters-46" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-46" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="container" tabindex="-1">container <a class="header-anchor" href="#container" aria-label="Permalink to “container”">​</a></h5><p><code>string</code></p><p>The container, as an <code>inventory-slot</code> entry names it.</p><h5 id="slot-1" tabindex="-1">slot <a class="header-anchor" href="#slot-1" aria-label="Permalink to “slot”">​</a></h5><p><code>number</code></p><p>The slot within that container.</p><h4 id="returns-107" tabindex="-1">Returns <a class="header-anchor" href="#returns-107" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>void</code>&gt;</p><p>The send, or a settled promise for a container the client has no window for.</p><hr><h3 id="sendplayerlist" tabindex="-1">sendPlayerList() <a class="header-anchor" href="#sendplayerlist" aria-label="Permalink to “sendPlayerList()”">​</a></h3><blockquote><p><strong>sendPlayerList</strong>(): <code>Promise</code>&lt;<code>void</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/1e6d90ea19aef765befd07dcc536f23d48c760b1/packages/prismarine/src/network/PlayerSession.ts#L2945" target="_blank" rel="noreferrer">prismarine/src/network/PlayerSession.ts:2945</a></p><p>Sends the full player list to the player.</p><h4 id="returns-108" tabindex="-1">Returns <a class="header-anchor" href="#returns-108" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>void</code>&gt;</p><hr><h3 id="sendplaystatus" tabindex="-1">sendPlayStatus() <a class="header-anchor" href="#sendplaystatus" aria-label="Permalink to “sendPlayStatus()”">​</a></h3><blockquote><p><strong>sendPlayStatus</strong>(<code>status</code>): <code>Promise</code>&lt;<code>void</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/1e6d90ea19aef765befd07dcc536f23d48c760b1/packages/prismarine/src/network/PlayerSession.ts#L3118" target="_blank" rel="noreferrer">prismarine/src/network/PlayerSession.ts:3118</a></p><p>Sends a <code>PlayStatus</code> to this player&#39;s client.</p><h4 id="parameters-47" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-47" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="status" tabindex="-1">status <a class="header-anchor" href="#status" aria-label="Permalink to “status”">​</a></h5><p><a href="./../../../../protocol/#playstatus"><code>PlayStatus</code></a></p><h4 id="returns-109" tabindex="-1">Returns <a class="header-anchor" href="#returns-109" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>void</code>&gt;</p><hr><h3 id="sendremoveactor" tabindex="-1">sendRemoveActor() <a class="header-anchor" href="#sendremoveactor" aria-label="Permalink to “sendRemoveActor()”">​</a></h3><blockquote><p><strong>sendRemoveActor</strong>(<code>entity</code>): <code>Promise</code>&lt;<code>void</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/1e6d90ea19aef765befd07dcc536f23d48c760b1/packages/prismarine/src/network/PlayerSession.ts#L2998" target="_blank" rel="noreferrer">prismarine/src/network/PlayerSession.ts:2998</a></p><p>Takes an entity off this connection.</p><h4 id="parameters-48" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-48" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="entity-6" tabindex="-1">entity <a class="header-anchor" href="#entity-6" aria-label="Permalink to “entity”">​</a></h5><p><code>ShownActor</code></p><p>The entity to remove.</p><h4 id="returns-110" tabindex="-1">Returns <a class="header-anchor" href="#returns-110" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>void</code>&gt;</p><hr><h3 id="sendremoveactorbyid" tabindex="-1">sendRemoveActorById() <a class="header-anchor" href="#sendremoveactorbyid" aria-label="Permalink to “sendRemoveActorById()”">​</a></h3><blockquote><p><strong>sendRemoveActorById</strong>(<code>runtimeId</code>): <code>Promise</code>&lt;<code>void</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/1e6d90ea19aef765befd07dcc536f23d48c760b1/packages/prismarine/src/network/PlayerSession.ts#L3010" target="_blank" rel="noreferrer">prismarine/src/network/PlayerSession.ts:3010</a></p><p>Takes an entity off this client by id.</p><p>By id rather than by entity because the tracker has to be able to hide something that has already left the world - there is no object left to ask. Correct for every kind of entity, players included: <code>RemoveActorPacket</code> names only the id.</p><h4 id="parameters-49" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-49" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="runtimeid-1" tabindex="-1">runtimeId <a class="header-anchor" href="#runtimeid-1" aria-label="Permalink to “runtimeId”">​</a></h5><p><code>bigint</code></p><p>The entity&#39;s runtime id.</p><h4 id="returns-111" tabindex="-1">Returns <a class="header-anchor" href="#returns-111" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>void</code>&gt;</p><hr><h3 id="sendrespawn" tabindex="-1">sendRespawn() <a class="header-anchor" href="#sendrespawn" aria-label="Permalink to “sendRespawn()”">​</a></h3><blockquote><p><strong>sendRespawn</strong>(<code>position</code>, <code>state</code>): <code>Promise</code>&lt;<code>void</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/1e6d90ea19aef765befd07dcc536f23d48c760b1/packages/prismarine/src/network/PlayerSession.ts#L2757" target="_blank" rel="noreferrer">prismarine/src/network/PlayerSession.ts:2757</a></p><p>One of the server&#39;s two halves of the respawn exchange.</p><p>The order matters and is not obvious. <code>SearchingForSpawn</code> goes out the moment the player dies, carrying where they will reappear; the client then shows its death screen. <code>ReadyToSpawn</code> is the <em>answer</em> to the client saying it has finished loading, and goes out only then.</p><p>Sending the second in place of the first leaves the client on &quot;Respawning&quot; for ever: it is waiting to be told where it will come back before it will even offer the button.</p><p><code>Player Runtime Id</code> is always 0, as in every <code>Respawn</code> a Bedrock Dedicated Server 1.26.52 sends, at the join and after a death.</p><h4 id="parameters-50" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-50" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="position-1" tabindex="-1">position <a class="header-anchor" href="#position-1" aria-label="Permalink to “position”">​</a></h5><p><a href="./../../../../math/classes/Vector3.html"><code>Vector3</code></a></p><p>Where the player will reappear.</p><h5 id="state" tabindex="-1">state <a class="header-anchor" href="#state" aria-label="Permalink to “state”">​</a></h5><p><a href="./../../../../minecraft/#playerrespawnstate"><code>PlayerRespawnState</code></a></p><p>Which half of the exchange this is.</p><h4 id="returns-112" tabindex="-1">Returns <a class="header-anchor" href="#returns-112" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>void</code>&gt;</p><h4 id="see-2" tabindex="-1">See <a class="header-anchor" href="#see-2" aria-label="Permalink to “See”">​</a></h4><p><a href="https://github.com/pmmp/PocketMine-MP/blob/stable/src/network/mcpe/handler/DeathPacketHandler.php" target="_blank" rel="noreferrer">https://github.com/pmmp/PocketMine-MP/blob/stable/src/network/mcpe/handler/DeathPacketHandler.php</a></p><hr><h3 id="sendrespawned" tabindex="-1">sendRespawned() <a class="header-anchor" href="#sendrespawned" aria-label="Permalink to “sendRespawned()”">​</a></h3><blockquote><p><strong>sendRespawned</strong>(): <code>Promise</code>&lt;<code>void</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/1e6d90ea19aef765befd07dcc536f23d48c760b1/packages/prismarine/src/network/PlayerSession.ts#L2725" target="_blank" rel="noreferrer">prismarine/src/network/PlayerSession.ts:2725</a></p><p>Tells the client its player is alive again, as a Bedrock Dedicated Server 1.26.52 does when the respawn button is pressed: <code>ActorEvent(SPAWN_ALIVE)</code> for the player, its health, then its attributes and actor data.</p><p>No <code>MovePlayer</code>: the client has put itself at the <code>ReadyToSpawn</code> position already.</p><h4 id="returns-113" tabindex="-1">Returns <a class="header-anchor" href="#returns-113" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>void</code>&gt;</p><hr><h3 id="sendsettings" tabindex="-1">sendSettings() <a class="header-anchor" href="#sendsettings" aria-label="Permalink to “sendSettings()”">​</a></h3><blockquote><p><strong>sendSettings</strong>(<code>player?</code>): <code>Promise</code>&lt;<code>void</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/1e6d90ea19aef765befd07dcc536f23d48c760b1/packages/prismarine/src/network/PlayerSession.ts#L1204" target="_blank" rel="noreferrer">prismarine/src/network/PlayerSession.ts:1204</a></p><p>Notify a client about change(s) to the adventure settings.</p><h4 id="parameters-51" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-51" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="player-3" tabindex="-1">player? <a class="header-anchor" href="#player-3" aria-label="Permalink to “player?”">​</a></h5><p><code>Pick</code>&lt;<code>ShownPlayer</code>, <code>&quot;gamemode&quot;</code>&gt;</p><p>The client-controlled entity</p><h4 id="returns-114" tabindex="-1">Returns <a class="header-anchor" href="#returns-114" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>void</code>&gt;</p><hr><h3 id="sendstatuseffect" tabindex="-1">sendStatusEffect() <a class="header-anchor" href="#sendstatuseffect" aria-label="Permalink to “sendStatusEffect()”">​</a></h3><blockquote><p><strong>sendStatusEffect</strong>(<code>entity</code>, <code>effect</code>, <code>change</code>): <code>Promise</code>&lt;<code>void</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/1e6d90ea19aef765befd07dcc536f23d48c760b1/packages/prismarine/src/network/PlayerSession.ts#L2966" target="_blank" rel="noreferrer">prismarine/src/network/PlayerSession.ts:2966</a></p><p>Sends one effect state change to this client.</p><h4 id="parameters-52" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-52" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="entity-7" tabindex="-1">entity <a class="header-anchor" href="#entity-7" aria-label="Permalink to “entity”">​</a></h5><p><code>Pick</code>&lt;<code>ShownActor</code>, <code>&quot;getRuntimeId&quot;</code>&gt;</p><p>The actor whose effect changed.</p><h5 id="effect" tabindex="-1">effect <a class="header-anchor" href="#effect" aria-label="Permalink to “effect”">​</a></h5><p><code>StatusEffect</code></p><p>The effect state.</p><h5 id="change" tabindex="-1">change <a class="header-anchor" href="#change" aria-label="Permalink to “change”">​</a></h5><p><code>StatusEffectChange</code></p><p>Whether it was added, updated, or removed.</p><h4 id="returns-115" tabindex="-1">Returns <a class="header-anchor" href="#returns-115" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>void</code>&gt;</p><hr><h3 id="sendstatuseffects" tabindex="-1">sendStatusEffects() <a class="header-anchor" href="#sendstatuseffects" aria-label="Permalink to “sendStatusEffects()”">​</a></h3><blockquote><p><strong>sendStatusEffects</strong>(<code>entity</code>): <code>Promise</code>&lt;<code>void</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/1e6d90ea19aef765befd07dcc536f23d48c760b1/packages/prismarine/src/network/PlayerSession.ts#L2956" target="_blank" rel="noreferrer">prismarine/src/network/PlayerSession.ts:2956</a></p><p>Sends every active effect after the actor that owns them has spawned.</p><h4 id="parameters-53" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-53" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="entity-8" tabindex="-1">entity <a class="header-anchor" href="#entity-8" aria-label="Permalink to “entity”">​</a></h5><p><code>ShownActor</code></p><p>The spawned actor.</p><h4 id="returns-116" tabindex="-1">Returns <a class="header-anchor" href="#returns-116" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>void</code>&gt;</p><hr><h3 id="sendtime" tabindex="-1">sendTime() <a class="header-anchor" href="#sendtime" aria-label="Permalink to “sendTime()”">​</a></h3><blockquote><p><strong>sendTime</strong>(<code>tick</code>): <code>Promise</code>&lt;<code>void</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/1e6d90ea19aef765befd07dcc536f23d48c760b1/packages/prismarine/src/network/PlayerSession.ts#L1937" target="_blank" rel="noreferrer">prismarine/src/network/PlayerSession.ts:1937</a></p><p>Send the current tick to a client.</p><h4 id="parameters-54" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-54" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="tick-1" tabindex="-1">tick <a class="header-anchor" href="#tick-1" aria-label="Permalink to “tick”">​</a></h5><p><code>number</code></p><p>The tick</p><h4 id="returns-117" tabindex="-1">Returns <a class="header-anchor" href="#returns-117" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>void</code>&gt;</p><hr><h3 id="sendtradeoffers" tabindex="-1">sendTradeOffers() <a class="header-anchor" href="#sendtradeoffers" aria-label="Permalink to “sendTradeOffers()”">​</a></h3><blockquote><p><strong>sendTradeOffers</strong>(<code>window?</code>): <code>Promise</code>&lt;<code>void</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/1e6d90ea19aef765befd07dcc536f23d48c760b1/packages/prismarine/src/network/PlayerSession.ts#L1741" target="_blank" rel="noreferrer">prismarine/src/network/PlayerSession.ts:1741</a></p><p>Sends the open trade screen the trader&#39;s offers as they stand, after a trade or a restock.</p><h4 id="parameters-55" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-55" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="window" tabindex="-1">window? <a class="header-anchor" href="#window" aria-label="Permalink to “window?”">​</a></h5><p><a href="./../#openblockcontainer"><code>OpenBlockContainer</code></a> | <code>undefined</code> = <code>...</code></p><h4 id="returns-118" tabindex="-1">Returns <a class="header-anchor" href="#returns-118" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>void</code>&gt;</p><hr><h3 id="setattributevalue" tabindex="-1">setAttributeValue() <a class="header-anchor" href="#setattributevalue" aria-label="Permalink to “setAttributeValue()”">​</a></h3><blockquote><p><strong>setAttributeValue</strong>(<code>name</code>, <code>value</code>): <code>boolean</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/1e6d90ea19aef765befd07dcc536f23d48c760b1/packages/prismarine/src/network/PlayerSession.ts#L3324" target="_blank" rel="noreferrer">prismarine/src/network/PlayerSession.ts:3324</a></p><p>Sets an attribute, through the component field it is kept in when it has one, so it is logged.</p><h4 id="parameters-56" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-56" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="name" tabindex="-1">name <a class="header-anchor" href="#name" aria-label="Permalink to “name”">​</a></h5><p><code>string</code></p><h5 id="value" tabindex="-1">value <a class="header-anchor" href="#value" aria-label="Permalink to “value”">​</a></h5><p><code>number</code></p><h4 id="returns-119" tabindex="-1">Returns <a class="header-anchor" href="#returns-119" aria-label="Permalink to “Returns”">​</a></h4><p><code>boolean</code></p><hr><h3 id="setclientcacheenabled" tabindex="-1">setClientCacheEnabled() <a class="header-anchor" href="#setclientcacheenabled" aria-label="Permalink to “setClientCacheEnabled()”">​</a></h3><blockquote><p><strong>setClientCacheEnabled</strong>(<code>enabled</code>): <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/1e6d90ea19aef765befd07dcc536f23d48c760b1/packages/prismarine/src/network/PlayerSession.ts#L749" target="_blank" rel="noreferrer">prismarine/src/network/PlayerSession.ts:749</a></p><p>Enables or clears client blob caching for subsequent subchunk requests.</p><h4 id="parameters-57" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-57" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="enabled" tabindex="-1">enabled <a class="header-anchor" href="#enabled" aria-label="Permalink to “enabled”">​</a></h5><p><code>boolean</code></p><h4 id="returns-120" tabindex="-1">Returns <a class="header-anchor" href="#returns-120" aria-label="Permalink to “Returns”">​</a></h4><p><code>void</code></p><hr><h3 id="setflying" tabindex="-1">setFlying() <a class="header-anchor" href="#setflying" aria-label="Permalink to “setFlying()”">​</a></h3><blockquote><p><strong>setFlying</strong>(<code>flying</code>): <code>Promise</code>&lt;<code>void</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/1e6d90ea19aef765befd07dcc536f23d48c760b1/packages/prismarine/src/network/PlayerSession.ts#L3445" target="_blank" rel="noreferrer">prismarine/src/network/PlayerSession.ts:3445</a></p><p>Starts or stops the player flying, after the <code>playerToggleFlight</code> event, and sends the settings. A game mode that may not fly only ever lands.</p><p>The flight is written and the settings queued before this returns.</p><h4 id="parameters-58" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-58" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="flying" tabindex="-1">flying <a class="header-anchor" href="#flying" aria-label="Permalink to “flying”">​</a></h5><p><code>boolean</code></p><h4 id="returns-121" tabindex="-1">Returns <a class="header-anchor" href="#returns-121" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>void</code>&gt;</p><hr><h3 id="setgamemode" tabindex="-1">setGamemode() <a class="header-anchor" href="#setgamemode" aria-label="Permalink to “setGamemode()”">​</a></h3><blockquote><p><strong>setGamemode</strong>(<code>mode?</code>): <code>Promise</code>&lt;<code>void</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/1e6d90ea19aef765befd07dcc536f23d48c760b1/packages/prismarine/src/network/PlayerSession.ts#L3418" target="_blank" rel="noreferrer">prismarine/src/network/PlayerSession.ts:3418</a></p><p>Changes the player&#39;s game mode, after the <code>playerSetGamemode</code> event, and tells this client and every client that caches it.</p><p>Every write is made, and every packet queued, before this returns. The promise only says when the transport has framed the packets.</p><h4 id="parameters-59" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-59" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="mode-1" tabindex="-1">mode? <a class="header-anchor" href="#mode-1" aria-label="Permalink to “mode?”">​</a></h5><p><a href="./../../../../minecraft/#gametype"><code>Gametype</code></a></p><p>The new mode; the current one by default, which sends it again.</p><h4 id="returns-122" tabindex="-1">Returns <a class="header-anchor" href="#returns-122" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>void</code>&gt;</p><hr><h3 id="setjoinspawn" tabindex="-1">setJoinSpawn() <a class="header-anchor" href="#setjoinspawn" aria-label="Permalink to “setJoinSpawn()”">​</a></h3><blockquote><p><strong>setJoinSpawn</strong>(<code>spawn</code>): <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/1e6d90ea19aef765befd07dcc536f23d48c760b1/packages/prismarine/src/network/PlayerSession.ts#L2105" target="_blank" rel="noreferrer">prismarine/src/network/PlayerSession.ts:2105</a></p><p>Records where the join placed the player, which the join packets report.</p><h4 id="parameters-60" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-60" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="spawn" tabindex="-1">spawn <a class="header-anchor" href="#spawn" aria-label="Permalink to “spawn”">​</a></h5><p><code>PlayerSpawn</code> | <code>null</code></p><p>The placement, or null for a player who came back to a saved position.</p><h4 id="returns-123" tabindex="-1">Returns <a class="header-anchor" href="#returns-123" aria-label="Permalink to “Returns”">​</a></h4><p><code>void</code></p><hr><h3 id="setonground" tabindex="-1">setOnGround() <a class="header-anchor" href="#setonground" aria-label="Permalink to “setOnGround()”">​</a></h3><blockquote><p><strong>setOnGround</strong>(<code>onGround</code>): <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/1e6d90ea19aef765befd07dcc536f23d48c760b1/packages/prismarine/src/network/PlayerSession.ts#L3682" target="_blank" rel="noreferrer">prismarine/src/network/PlayerSession.ts:3682</a></p><p>Records whether the client reports the player on the ground, as a move to where the player already is: the store pays for a fall the moment it lands.</p><h4 id="parameters-61" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-61" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="onground" tabindex="-1">onGround <a class="header-anchor" href="#onground" aria-label="Permalink to “onGround”">​</a></h5><p><code>boolean</code></p><h4 id="returns-124" tabindex="-1">Returns <a class="header-anchor" href="#returns-124" aria-label="Permalink to “Returns”">​</a></h4><p><code>void</code></p><hr><h3 id="setplayerposition" tabindex="-1">setPlayerPosition() <a class="header-anchor" href="#setplayerposition" aria-label="Permalink to “setPlayerPosition()”">​</a></h3><blockquote><p><strong>setPlayerPosition</strong>(<code>options</code>, <code>broadcast?</code>): <code>Promise</code>&lt;<code>void</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/1e6d90ea19aef765befd07dcc536f23d48c760b1/packages/prismarine/src/network/PlayerSession.ts#L3712" target="_blank" rel="noreferrer">prismarine/src/network/PlayerSession.ts:3712</a></p><p>Moves the player, with a movement mode.</p><p>The client owns a player&#39;s movement (ADR 0008), so a move the server makes is a request the client has to acknowledge, and the positions it reports until then are dropped (<a href="#holdsmovementforteleport">PlayerSession.holdsMovementForTeleport</a>).</p><h4 id="parameters-62" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-62" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="options-1" tabindex="-1">options <a class="header-anchor" href="#options-1" aria-label="Permalink to “options”">​</a></h5><p>The options to set the position.</p><h6 id="headyaw" tabindex="-1">headYaw? <a class="header-anchor" href="#headyaw" aria-label="Permalink to “headYaw?”">​</a></h6><p><code>number</code></p><p>The new head yaw.</p><h6 id="pitch-1" tabindex="-1">pitch? <a class="header-anchor" href="#pitch-1" aria-label="Permalink to “pitch?”">​</a></h6><p><code>number</code></p><p>The new pitch.</p><h6 id="position-2" tabindex="-1">position <a class="header-anchor" href="#position-2" aria-label="Permalink to “position”">​</a></h6><p><a href="./../../../../math/classes/Vector3.html"><code>Vector3</code></a></p><p>The new eye position. A Position in another world, given while the player is in no store, is the world it enters next.</p><h6 id="type-1" tabindex="-1">type? <a class="header-anchor" href="#type-1" aria-label="Permalink to “type?”">​</a></h6><p><a href="./../../../../protocol/#positionmode"><code>PositionMode</code></a> = <code>PositionMode.Normal</code></p><p>The position mode.</p><h6 id="yaw-1" tabindex="-1">yaw? <a class="header-anchor" href="#yaw-1" aria-label="Permalink to “yaw?”">​</a></h6><p><code>number</code></p><p>The new yaw.</p><h5 id="broadcast" tabindex="-1">broadcast? <a class="header-anchor" href="#broadcast" aria-label="Permalink to “broadcast?”">​</a></h5><p><code>boolean</code> = <code>true</code></p><p>Whether to tell this client.</p><h4 id="returns-125" tabindex="-1">Returns <a class="header-anchor" href="#returns-125" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>void</code>&gt;</p><h4 id="remarks-4" tabindex="-1">Remarks <a class="header-anchor" href="#remarks-4" aria-label="Permalink to “Remarks”">​</a></h4><p>Observers snap to a respawn or a teleport instead of interpolating to it.</p><hr><h3 id="setspawnpoint" tabindex="-1">setSpawnPoint() <a class="header-anchor" href="#setspawnpoint" aria-label="Permalink to “setSpawnPoint()”">​</a></h3><blockquote><p><strong>setSpawnPoint</strong>(<code>spawn</code>): <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/1e6d90ea19aef765befd07dcc536f23d48c760b1/packages/prismarine/src/network/PlayerSession.ts#L3334" target="_blank" rel="noreferrer">prismarine/src/network/PlayerSession.ts:3334</a></p><p>Moves the player&#39;s own spawn point, or clears it back to the world spawn.</p><h4 id="parameters-63" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-63" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="spawn-1" tabindex="-1">spawn <a class="header-anchor" href="#spawn-1" aria-label="Permalink to “spawn”">​</a></h5><p><code>StoredSpawnPoint</code> | <code>undefined</code></p><h4 id="returns-126" tabindex="-1">Returns <a class="header-anchor" href="#returns-126" aria-label="Permalink to “Returns”">​</a></h4><p><code>void</code></p><hr><h3 id="setsprinting" tabindex="-1">setSprinting() <a class="header-anchor" href="#setsprinting" aria-label="Permalink to “setSprinting()”">​</a></h3><blockquote><p><strong>setSprinting</strong>(<code>sprinting</code>): <code>Promise</code>&lt;<code>void</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/1e6d90ea19aef765befd07dcc536f23d48c760b1/packages/prismarine/src/network/PlayerSession.ts#L3463" target="_blank" rel="noreferrer">prismarine/src/network/PlayerSession.ts:3463</a></p><p>Starts or stops the player sprinting, after the <code>playerToggleSprint</code> event.</p><h4 id="parameters-64" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-64" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="sprinting" tabindex="-1">sprinting <a class="header-anchor" href="#sprinting" aria-label="Permalink to “sprinting”">​</a></h5><p><code>boolean</code></p><h4 id="returns-127" tabindex="-1">Returns <a class="header-anchor" href="#returns-127" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>void</code>&gt;</p><hr><h3 id="setviewdistance" tabindex="-1">setViewDistance() <a class="header-anchor" href="#setviewdistance" aria-label="Permalink to “setViewDistance()”">​</a></h3><blockquote><p><strong>setViewDistance</strong>(<code>distance</code>): <code>Promise</code>&lt;<code>void</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/1e6d90ea19aef765befd07dcc536f23d48c760b1/packages/prismarine/src/network/PlayerSession.ts#L2172" target="_blank" rel="noreferrer">prismarine/src/network/PlayerSession.ts:2172</a></p><p>Set the client&#39;s maximum view distance.</p><h4 id="parameters-65" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-65" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="distance-1" tabindex="-1">distance <a class="header-anchor" href="#distance-1" aria-label="Permalink to “distance”">​</a></h5><p><code>number</code></p><p>The view distance</p><h4 id="returns-128" tabindex="-1">Returns <a class="header-anchor" href="#returns-128" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>void</code>&gt;</p><hr><h3 id="setworld" tabindex="-1">setWorld() <a class="header-anchor" href="#setworld" aria-label="Permalink to “setWorld()”">​</a></h3><blockquote><p><strong>setWorld</strong>(<code>world</code>): <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/1e6d90ea19aef765befd07dcc536f23d48c760b1/packages/prismarine/src/network/PlayerSession.ts#L3486" target="_blank" rel="noreferrer">prismarine/src/network/PlayerSession.ts:3486</a></p><p>Moves the player to another world, arriving at that world&#39;s spawn.</p><p>The stored spawn is the block under a joining player&#39;s feet, so the feet go one block above it, centered, as <code>requestedSpawnPosition</code> says before the terrain is consulted. The move is a message: <code>DimensionTravel.moveTo</code> files it, a world that has not found its spawn searches for it outside every tick, and the next input step at which the spawn is known carries out <a href="#changeworld">PlayerSession.changeWorld</a>. This is the entry point for callers that have a world and no arrival of their own, such as the <code>changeWorld</code> command.</p><h4 id="parameters-66" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-66" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="world-1" tabindex="-1">world <a class="header-anchor" href="#world-1" aria-label="Permalink to “world”">​</a></h5><p><a href="./../../../world/World/classes/World.html"><code>World</code></a></p><p>The new world.</p><h4 id="returns-129" tabindex="-1">Returns <a class="header-anchor" href="#returns-129" aria-label="Permalink to “Returns”">​</a></h4><p><code>void</code></p><hr><h3 id="shown" tabindex="-1">shown() <a class="header-anchor" href="#shown" aria-label="Permalink to “shown()”">​</a></h3><blockquote><p><strong>shown</strong>(): <code>ShownPlayer</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/1e6d90ea19aef765befd07dcc536f23d48c760b1/packages/prismarine/src/network/PlayerSession.ts#L3191" target="_blank" rel="noreferrer">prismarine/src/network/PlayerSession.ts:3191</a></p><p>The session&#39;s own player as clients are shown it: its actor while it is in a store, and otherwise what this client is shown of it before its spawn and between two worlds.</p><h4 id="returns-130" tabindex="-1">Returns <a class="header-anchor" href="#returns-130" aria-label="Permalink to “Returns”">​</a></h4><p><code>ShownPlayer</code></p><p>The player as it is shown.</p><h4 id="throws-1" tabindex="-1">Throws <a class="header-anchor" href="#throws-1" aria-label="Permalink to “Throws”">​</a></h4><p>Once <a href="#disable">PlayerSession.disable</a> has forgotten the player.</p><hr><h3 id="startcredits" tabindex="-1">startCredits() <a class="header-anchor" href="#startcredits" aria-label="Permalink to “startCredits()”">​</a></h3><blockquote><p><strong>startCredits</strong>(<code>arrival</code>): <code>Promise</code>&lt;<code>void</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/1e6d90ea19aef765befd07dcc536f23d48c760b1/packages/prismarine/src/network/PlayerSession.ts#L2548" target="_blank" rel="noreferrer">prismarine/src/network/PlayerSession.ts:2548</a></p><p>Rolls the end credits on the client and holds the arrival until they finish.</p><p>Sent on a player&#39;s first exit through the End&#39;s portal. The world change waits for the client&#39;s <code>ShowCredits Finished</code> rather than going out under the credits screen, because a <code>ChangeDimension</code> during the credits has not been verified against a retail client (open question 4 of the End dragon fight plan); Java holds its transfer the same way, on the <code>PERFORM_RESPAWN</code> exchange. While the arrival is held, the client&#39;s <code>PlayerAuthInput</code> is dropped, as during a pending dimension change. The held change is completed by <a href="#completecredits">PlayerSession.completeCredits</a>. A disconnect in between strands nobody: the player record already carries <code>seenCredits</code>, so the next join finds the player still in the End, standing in the portal, and transfers them at once.</p><p>A second start while one is pending is logged at debug and dropped, like a second <code>changeWorld</code>.</p><h4 id="parameters-67" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-67" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="arrival-1" tabindex="-1">arrival <a class="header-anchor" href="#arrival-1" aria-label="Permalink to “arrival”">​</a></h5><p><a href="./../#arrival"><code>Arrival</code></a></p><p>Where the player lands once the credits are over.</p><h4 id="returns-131" tabindex="-1">Returns <a class="header-anchor" href="#returns-131" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>void</code>&gt;</p><p>Settles once the transport has framed the packet, which is queued before this returns.</p><hr><h3 id="stopmining" tabindex="-1">stopMining() <a class="header-anchor" href="#stopmining" aria-label="Permalink to “stopMining()”">​</a></h3><blockquote><p><strong>stopMining</strong>(): <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/1e6d90ea19aef765befd07dcc536f23d48c760b1/packages/prismarine/src/network/PlayerSession.ts#L3401" target="_blank" rel="noreferrer">prismarine/src/network/PlayerSession.ts:3401</a></p><p>Stops the cracks on the block the player was mining, if any, and forgets it.</p><p>For whatever ends the mining without the client saying so: a disconnect, a change of game mode or of world. A death is the player systems&#39;, inside the blow. Left alone, the cracks would go out every tick for good.</p><h4 id="returns-132" tabindex="-1">Returns <a class="header-anchor" href="#returns-132" aria-label="Permalink to “Returns”">​</a></h4><p><code>void</code></p><hr><h3 id="syncattributes" tabindex="-1">syncAttributes() <a class="header-anchor" href="#syncattributes" aria-label="Permalink to “syncAttributes()”">​</a></h3><blockquote><p><strong>syncAttributes</strong>(): <code>Promise</code>&lt;<code>void</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/1e6d90ea19aef765befd07dcc536f23d48c760b1/packages/prismarine/src/network/PlayerSession.ts#L2254" target="_blank" rel="noreferrer">prismarine/src/network/PlayerSession.ts:2254</a></p><p>Send only the attributes that changed since the last sync, if any.</p><p>Called every tick from the player&#39;s update: a value nothing tells the client about is a value that only exists on the server.</p><h4 id="returns-133" tabindex="-1">Returns <a class="header-anchor" href="#returns-133" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>void</code>&gt;</p><hr><h3 id="tracks" tabindex="-1">tracks() <a class="header-anchor" href="#tracks" aria-label="Permalink to “tracks()”">​</a></h3><blockquote><p><strong>tracks</strong>(<code>runtimeId</code>): <code>boolean</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/1e6d90ea19aef765befd07dcc536f23d48c760b1/packages/prismarine/src/network/PlayerSession.ts#L971" target="_blank" rel="noreferrer">prismarine/src/network/PlayerSession.ts:971</a></p><p>Whether this client knows about the entity.</p><p>True for the player&#39;s own entity, which the tracker itself never holds - a client is not sent a spawn for the thing it is driving, but it plainly <em>has</em> it. Without this the gates built on <code>tracks</code> would drop a player&#39;s own hurt animation and the pickup animation for the item they just walked over.</p><h4 id="parameters-68" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-68" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="runtimeid-2" tabindex="-1">runtimeId <a class="header-anchor" href="#runtimeid-2" aria-label="Permalink to “runtimeId”">​</a></h5><p><code>bigint</code></p><p>The entity&#39;s runtime id.</p><h4 id="returns-134" tabindex="-1">Returns <a class="header-anchor" href="#returns-134" aria-label="Permalink to “Returns”">​</a></h4><p><code>boolean</code></p><p><code>true</code> if the client can act on a packet naming that id.</p><hr><h3 id="trydeliverloaded" tabindex="-1">tryDeliverLoaded() <a class="header-anchor" href="#trydeliverloaded" aria-label="Permalink to “tryDeliverLoaded()”">​</a></h3><blockquote><p><strong>tryDeliverLoaded</strong>(<code>x</code>, <code>z</code>): <code>CachedChunkDelivery</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/1e6d90ea19aef765befd07dcc536f23d48c760b1/packages/prismarine/src/network/PlayerSession.ts#L736" target="_blank" rel="noreferrer">prismarine/src/network/PlayerSession.ts:736</a></p><p>Queues a resident chunk without entering the generation and disk-read depth gate.</p><h4 id="parameters-69" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-69" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="x-2" tabindex="-1">x <a class="header-anchor" href="#x-2" aria-label="Permalink to “x”">​</a></h5><p><code>number</code></p><h5 id="z-2" tabindex="-1">z <a class="header-anchor" href="#z-2" aria-label="Permalink to “z”">​</a></h5><p><code>number</code></p><h4 id="returns-135" tabindex="-1">Returns <a class="header-anchor" href="#returns-135" aria-label="Permalink to “Returns”">​</a></h4><p><code>CachedChunkDelivery</code></p><hr><h3 id="update" tabindex="-1">update() <a class="header-anchor" href="#update" aria-label="Permalink to “update()”">​</a></h3><blockquote><p><strong>update</strong>(<code>tick</code>): <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/1e6d90ea19aef765befd07dcc536f23d48c760b1/packages/prismarine/src/network/PlayerSession.ts#L919" target="_blank" rel="noreferrer">prismarine/src/network/PlayerSession.ts:919</a></p><p>Per-tick work for this client: terrain to request, entities to show or hide.</p><p>Both hang off the same question - has the player walked into a different chunk. Asking it here rather than inside each is what stops <code>needNewChunks</code> rebuilding a heap of a few hundred candidates twenty times a second for a player who has not moved, and it is what makes a moving player see entities appear within a tick rather than on the next interval.</p><h4 id="parameters-70" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-70" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="tick-2" tabindex="-1">tick <a class="header-anchor" href="#tick-2" aria-label="Permalink to “tick”">​</a></h5><p><code>number</code></p><h4 id="returns-136" tabindex="-1">Returns <a class="header-anchor" href="#returns-136" aria-label="Permalink to “Returns”">​</a></h4><p><code>void</code></p><hr><h3 id="updateplayer" tabindex="-1">updatePlayer() <a class="header-anchor" href="#updateplayer" aria-label="Permalink to “updatePlayer()”">​</a></h3><blockquote><p><strong>updatePlayer</strong>(<code>tick</code>): <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/1e6d90ea19aef765befd07dcc536f23d48c760b1/packages/prismarine/src/network/PlayerSession.ts#L3367" target="_blank" rel="noreferrer">prismarine/src/network/PlayerSession.ts:3367</a></p><p>Runs the player&#39;s own part of a tick, which its actor runs after the entity&#39;s part: this session, the attribute sync and the triggers. Breath, hunger, a meal, the void and the mining cracks are the store&#39;s, in its entity pass.</p><h4 id="parameters-71" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-71" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="tick-3" tabindex="-1">tick <a class="header-anchor" href="#tick-3" aria-label="Permalink to “tick”">​</a></h5><p><code>number</code></p><p>The current world-tick.</p><h4 id="returns-137" tabindex="-1">Returns <a class="header-anchor" href="#returns-137" aria-label="Permalink to “Returns”">​</a></h4><p><code>void</code></p><h2 id="lifecycle" tabindex="-1">Lifecycle <a class="header-anchor" href="#lifecycle" aria-label="Permalink to “Lifecycle”">​</a></h2><h3 id="disable" tabindex="-1">disable() <a class="header-anchor" href="#disable" aria-label="Permalink to “disable()”">​</a></h3><blockquote><p><strong>disable</strong>(): <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/1e6d90ea19aef765befd07dcc536f23d48c760b1/packages/prismarine/src/network/PlayerSession.ts#L565" target="_blank" rel="noreferrer">prismarine/src/network/PlayerSession.ts:565</a></p><p>Takes this client back out of the chunk rotation and off every boss bar, lets go of the player&#39;s state kept outside the player, and forgets the player itself, after which <a href="#getplayer">PlayerSession.getPlayer</a> throws. Paired with <a href="#enable">PlayerSession.enable</a> and safe to call more than once.</p><p><a href="#leave">PlayerSession.leave</a> runs this after the player has been saved and taken off the server, whether or not that succeeded or the join ever completed.</p><h4 id="returns-138" tabindex="-1">Returns <a class="header-anchor" href="#returns-138" aria-label="Permalink to “Returns”">​</a></h4><p><code>void</code></p><hr><h3 id="enable" tabindex="-1">enable() <a class="header-anchor" href="#enable" aria-label="Permalink to “enable()”">​</a></h3><blockquote><p><strong>enable</strong>(): <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/1e6d90ea19aef765befd07dcc536f23d48c760b1/packages/prismarine/src/network/PlayerSession.ts#L551" target="_blank" rel="noreferrer">prismarine/src/network/PlayerSession.ts:551</a></p><p>Puts this client into the server-wide rotation that feeds it chunks.</p><p>Not done in the constructor: a session that is built and then thrown away - a join that fails part way through - would stay in the scheduler&#39;s set for the life of the server, because the scheduler only ever skips the disconnected and removes on request.</p><h4 id="returns-139" tabindex="-1">Returns <a class="header-anchor" href="#returns-139" aria-label="Permalink to “Returns”">​</a></h4><p><code>void</code></p><hr><h3 id="join" tabindex="-1">join() <a class="header-anchor" href="#join" aria-label="Permalink to “join()”">​</a></h3><blockquote><p><strong>join</strong>(): <code>Promise</code>&lt;<code>void</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/1e6d90ea19aef765befd07dcc536f23d48c760b1/packages/prismarine/src/network/PlayerSession.ts#L613" target="_blank" rel="noreferrer">prismarine/src/network/PlayerSession.ts:613</a></p><p>Loads what the server knows about this session&#39;s player and marks it joined.</p><h4 id="returns-140" tabindex="-1">Returns <a class="header-anchor" href="#returns-140" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>void</code>&gt;</p><h4 id="remarks-5" tabindex="-1">Remarks <a class="header-anchor" href="#remarks-5" aria-label="Permalink to “Remarks”">​</a></h4><p>Sends nothing. This runs from <code>LoginHandler</code>, before the client has been told its login succeeded, and a retail client at protocol 2193 that is handed game packets in that state drops the connection with <code>InitialConnection-90</code> (bad packet). The game mode, adventure settings and abilities go out from the join burst after <code>StartGame</code>, and <code>AddPlayer</code> carries each other player&#39;s position when they come into view.</p><hr><h3 id="leave" tabindex="-1">leave() <a class="header-anchor" href="#leave" aria-label="Permalink to “leave()”">​</a></h3><blockquote><p><strong>leave</strong>(): <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/1e6d90ea19aef765befd07dcc536f23d48c760b1/packages/prismarine/src/network/PlayerSession.ts#L590" target="_blank" rel="noreferrer">prismarine/src/network/PlayerSession.ts:590</a></p><p>Takes the player off the server and then this session down with it: the player is saved, taken out of its world and the player list, and said to have left, and <a href="#disable">PlayerSession.disable</a> runs whether or not that succeeded.</p><p><code>ClientConnection.closePlayerSession</code> calls this once per connection. Outside a unit of the world&#39;s change log, every write is made and every packet queued before this returns. Inside one, such as a kick from an input, all of it waits for the unit to end, whether it commits or is undone. The record&#39;s save is handed to work outside the tick, and a later read of the record waits for it.</p><h4 id="returns-141" tabindex="-1">Returns <a class="header-anchor" href="#returns-141" aria-label="Permalink to “Returns”">​</a></h4><p><code>void</code></p><h4 id="throws-2" tabindex="-1">Throws <a class="header-anchor" href="#throws-2" aria-label="Permalink to “Throws”">​</a></h4><p>What the player&#39;s leave threw, after the session is disabled, when no unit is open. Inside one, the store reports it.</p>`,1513)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};